def _base_class_repr(node: ast.expr) -> str:
    """Reconstructs a base-class expression's dotted name (`models.Model`, `mail.thread.Whatever`,
    etc.) from its AST node -- `ast.Attribute`/`ast.Name` only, the two shapes a real class
    statement's base list ever uses in generated code. Anything else (a call, a subscript) returns
    "" -- deliberately not a real Odoo base shape, never matched by this validator's own check.
    """
    if isinstance(node, ast.Attribute):
        value = _base_class_repr(node.value)
        return f"{value}.{node.attr}" if value else node.attr
    if isinstance(node, ast.Name):
        return node.id
    return ""


def _validate_model_declares_name_or_inherit(generated: GeneratedModuleFiles) -> None:
    """6th narrow validator (2026-08-04): added after this exact failure shape was independently
    observed FOUR separate times across one night's real sweep (task004, task016, task019/027,
    task028) -- a generated `class X(models.Model):` (or TransientModel/AbstractModel) with
    neither a `_name` nor an `_inherit` class attribute has no real model identity at all; Odoo
    raises `ValueError: The _name attribute None is not valid` (or, per task004/016/027's own
    live traceback, a similarly invalid derived name) directly at registry-build time -- a 100%
    deterministic, mechanical, AST-checkable defect, exactly the same shape as the other 5 narrow
    validators in this list (cheap, no model judgment required, no false-positive risk).

    Uses `ast.parse` (never regex) specifically because `_name`/`_inherit` can legally appear
    ANYWHERE in a class body (not just the first few lines), and a naive line-scoped regex would
    both false-positive (matching a comment/docstring mentioning `_name`) and false-negative (a
    class body spanning past whatever window a regex anchors on) -- the same syntax-only,
    never-executes-content discipline already used elsewhere in this file (see the ast.parse
    call sites above, all comment-flagged the same way).

    Deliberately silent (no ValueError) on a genuine ast.SyntaxError -- catching malformed Python
    is a different validator's job (this one only judges class shape, given valid syntax).
    """
    try:
        tree = ast.parse(generated.models_py)
    except SyntaxError:
        return

    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        base_names = {_base_class_repr(base) for base in node.bases}
        if not base_names & {"models.Model", "models.TransientModel", "models.AbstractModel"}:
            continue
        declares_identity = any(
            isinstance(stmt, ast.Assign)
            and any(isinstance(t, ast.Name) and t.id in ("_name", "_inherit") for t in stmt.targets)
            for stmt in node.body
        )
        if not declares_identity:
            raise ValueError(
                f"class '{node.name}' declares neither _name nor _inherit -- it has no real "
                f"model identity at all; Odoo raises directly at registry-build time."
            )


_ODOO_OBJECT_NAME_RE = re.compile(r'^[a-z0-9_.]+$')


def _validate_name_attribute_matches_odoo_naming_convention(generated: GeneratedModuleFiles) -> None:
    """7th narrow validator (2026-08-04): a real, confirmed-live-three-times-in-one-night sibling
    defect to `_validate_model_declares_name_or_inherit` above -- that validator only checks
    `_name` is PRESENT, not that its value is actually a legal Odoo model name. Three independent
    tasks in the same sweep (task016, task022, task027) generated a Python-class-style `_name`
    (`'ProjectMeerwerk'`, `'InvoiceSummary'`) instead of Odoo's required dotted-lowercase form
    (`'project.meerwerk'`, `'invoice.summary'`), and all three failed at registry-build time with
    the exact same live traceback: `ValueError: The _name attribute ProjectMeerwerk is not valid.`
    Confirmed against this deployment's own real `odoo/models.py` (not assumed/guessed): Odoo's
    `check_object_name()` uses `regex_object_name = re.compile(r'^[a-z0-9_.]+$')` -- lowercase
    letters, digits, underscore, and dot only, nothing else. This validator reuses that exact
    regex rather than inventing a stricter approximation (e.g. requiring a dot) that could
    false-positive on a legal single-word `_name` Odoo itself would accept.

    Only checks `_name` (never `_inherit` -- an `_inherit`-only class extending an existing model
    never declares a new object name, so there is nothing here to validate for it). Only fires
    when `_name` is assigned a plain string literal (`ast.Constant` with a `str` value) -- an
    f-string, variable, or other dynamic expression is a different, much rarer shape this
    validator deliberately does not attempt to evaluate.
    """
    try:
        tree = ast.parse(generated.models_py)
    except SyntaxError:
        return

    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        base_names = {_base_class_repr(base) for base in node.bases}
        if not base_names & {"models.Model", "models.TransientModel", "models.AbstractModel"}:
            continue
        for stmt in node.body:
            if not (
                isinstance(stmt, ast.Assign)
                and any(isinstance(t, ast.Name) and t.id == "_name" for t in stmt.targets)
            ):
                continue
            value = stmt.value
            if not (isinstance(value, ast.Constant) and isinstance(value.value, str)):
                continue
            name_value = value.value
            if not _ODOO_OBJECT_NAME_RE.match(name_value):
                raise ValueError(
                    f"class '{node.name}' declares _name = {name_value!r}, which is not a valid "
                    f"Odoo model name -- Odoo requires lowercase letters, digits, underscores, "
                    f"and dots only (e.g. 'project.meerwerk', not '{name_value}'); Odoo raises "
                    f"directly at registry-build time with this exact deployment's own "
                    f"check_object_name() regex."
                )


_MODEL_IDENTITY_ONLY_ATTRS = {
    "_name", "_inherit", "_description", "_order", "_rec_name", "_table", "_auto",
    "_log_access", "_check_company_auto",
}


def _validate_model_class_is_not_a_pure_identity_stub(generated: GeneratedModuleFiles, goal: str = "") -> None:
    """8th narrow validator (2026-08-04): a real, confirmed-live-3x-in-one-night sibling defect
    (task021, task025, task028, same full 30-task sweep) distinct from the 6th/7th validators
    above -- those catch a class with NO real model identity at all; this one catches the
    opposite-but-equally-broken shape: a class with a perfectly VALID `_name`/`_inherit` (so
    validators 6/7 see nothing wrong and it installs cleanly) but whose entire body is otherwise
    just identity/metadata attributes (`_name`, `_inherit`, `_description`, ...) -- zero field
    declarations, zero method definitions, zero real content of any kind. task025's own real,
    live Code-Review finding described this exactly: "no real statement content beyond its own
    class header/_name/_inherit/_description -- no field declarations, no method bodies." This
    installs without error (nothing here is syntactically or structurally invalid to Odoo) and so
    was never caught by any install-time check -- only ever caught downstream, expensively, by
    Testing/QA's reproduction check or Code-Review's own reading of the diff, after the round's
    real work was already spent.

    Deliberately structural, not goal-aware: a class whose ENTIRE body is drawn from
    `_MODEL_IDENTITY_ONLY_ATTRS` (no field assignment, no method, no other statement of any kind)
    is never a legitimate answer to any task -- every real task adds at least one field or method.
    Never flags a class with a docstring only, or one that adds a field but no method (or vice
    versa) -- only the genuinely, entirely empty shape.

    Real, confirmed gap (2026-08-07, HUMAN_DECISION push, task007, real task_id
    ce4951d0-9540-4c21-ab45-824a5b876d5b): a genuinely, deliberately views-only task ("add a quick
    filter button to the list") legitimately has NO field/method content to add to models.py at
    all -- the round's own real, correct work lives entirely in a `<record model="ir.ui.view">`
    in views_xml. This validator's own "never goal-aware" design correctly flagged the identity-
    only models.py class every time, forcing a pointless internal-fix-loop retry (nothing in
    models.py could ever satisfy this check for a legitimately views-only task) that was
    independently, reproducibly triggering a real `qwen3-coder-30b-a3b` repetition-loop bug 5
    times in a row. Exempted: an identity-only class is legitimate when views_xml already contains
    a real `<filter` search-view element (the round's real content genuinely lives there instead).
    Deliberately narrow (checks for `<filter`, not any `<record`) -- a bare `<record>` view edit
    doesn't by itself prove no model field/method was needed; a real quick-filter addition does.
    """
    if generated.views_xml and "<filter" in generated.views_xml:
        return
    if (
        generated.views_xml
        and _IR_UI_VIEW_RECORD_RE.search(generated.views_xml)
        and _GOAL_BUILD_VIEWS_INTENT_RE.search(goal or "")
    ):
        # Real, confirmed gap (2026-08-07, task025 v5): mirrors the sibling
        # `_validate_models_py_has_real_non_comment_content`'s own goal-gated relaxation -- a bare
        # `<record model="ir.ui.view">` alone is not a safe goal-independent signal (unlike a real
        # `<filter` element), since a task genuinely needing both a field AND a view must still be
        # caught if the field was forgotten.
        return
    try:
        tree = ast.parse(generated.models_py)
    except SyntaxError:
        return

    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        base_names = {_base_class_repr(base) for base in node.bases}
        if not base_names & {"models.Model", "models.TransientModel", "models.AbstractModel"}:
            continue
        real_stmts = [
            stmt for stmt in node.body
            if not (
                isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Constant)
                and isinstance(stmt.value.value, str)  # a bare docstring
            )
        ]
        if not real_stmts:
            continue  # an empty class body (just "pass" or nothing) is a different validator's job
        identity_only = all(
            isinstance(stmt, ast.Assign)
            and any(isinstance(t, ast.Name) and t.id in _MODEL_IDENTITY_ONLY_ATTRS for t in stmt.targets)
            for stmt in real_stmts
        )
        if identity_only:
            raise ValueError(
                f"class '{node.name}' has no real content at all -- its entire body is just "
                f"identity/metadata attributes ({sorted(_MODEL_IDENTITY_ONLY_ATTRS)}), with zero "
                f"field declarations and zero method definitions. This installs without error but "
                f"is never a correct answer to any real task; the round's own actual field/method "
                f"content is missing."
            )


_ENV_MODEL_LOOKUP_RE = re.compile(r"""\benv\[\s*(['"])([^'"]+)\1\s*\]""")


def _validate_env_model_lookup_uses_dotted_model_name(generated: GeneratedModuleFiles) -> None:
    """Real, confirmed root cause found live (2026-08-05, same-night full 30-task sweep, task026
    -- traced by pulling the actual committed content off gitea, not guessed from the Code-Review
    text alone): `self.env['container']` -- the real model this task needed is `waste.container`
    (built by an earlier task in this same benchmark), but the LLM invented a shorter, plausible-
    sounding bare name instead. Odoo raises `KeyError` at runtime the moment this code path
    executes -- `self.env[...]` is the real model-registry accessor, and every real Odoo model,
    with zero exceptions (every built-in core model and every real custom model observed all
    night), uses the dotted `module.model` naming convention -- the exact same rule this file's
    own sibling validator (`_validate_name_attribute_matches_odoo_naming_convention`) already
    enforces for a class's own `_name=`/`_inherit=` declaration, just extended here to any
    `env[...]` REFERENCE to another model elsewhere in the same file.

    Deliberately does NOT attempt a live existence check (unlike most validators in this file):
    the shared live-lookup helpers this project already has (`get_model_fields`/
    `get_model_fields_fast`) collapse "the model genuinely doesn't exist" and "the live query
    itself failed for an unrelated reason" into the exact same `None` return by design (see their
    own docstrings) -- reusing either one here to flag a real model as a false hallucination
    during a transient connectivity hiccup would be a genuine, real false-positive risk this
    project's own established discipline elsewhere always avoids. The dot-in-the-name rule below
    needs no live call at all and has no such risk: it is a 100% deterministic, structural,
    zero-judgment fact about Odoo's own naming convention, exactly like validator 7 above.
    """
    for match in _ENV_MODEL_LOOKUP_RE.finditer(generated.models_py):
        model_name = match.group(2)
        if "." not in model_name:
            raise ValueError(
                f"generated models_py calls env[{model_name!r}] -- every real Odoo model name "
                f"(built-in or custom) uses the dotted 'module.model' convention with no "
                f"exceptions; a bare, undotted name like this can never resolve to a real model "
                f"and always raises KeyError at runtime. Use the actual, real dotted technical "
                f"name of the target model."
            )


def _validate_portal_mixin_no_field_redeclaration(generated: GeneratedModuleFiles) -> None:
    """P11 Tier B item 47 (expert design §6.10.4). A model inheriting portal.mixin already
    provides access_token/access_url/access_warning -- redeclaring any of them shadows the
    mixin's own real implementation, same "later declaration silently shadows" failure mode as
    items 12/16 above.
    """
    inherits = _inherit_target_names(generated.models_py)
    if "portal.mixin" not in " ".join(inherits):
        return
    portal_fields = {"access_token", "access_url", "access_warning"}
    redeclared = sorted(set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) & portal_fields)
    if redeclared:
        raise ValueError(
            f"this model inherits portal.mixin (which already provides {sorted(portal_fields)}), "
            f"but re-declares {redeclared} -- this shadows the mixin's own real implementation."
        )


def _validate_qweb_report_template_id_resolves(generated: GeneratedModuleFiles) -> None:
    """P11 Tier B item 48 (expert design §6.11.1) -- same confirmed-real precedent family as item
    36 (`_validate_qweb_template_names_unique_and_calls_resolve`). An ir.actions.report's own
    report_name must resolve to a real <template id=...> defined somewhere in this module.
    """
    all_content = "\n".join(
        c for c in (generated.security_xml, *(generated.extra_data_files or {}).values()) if c
    )
    if not all_content or 'model="ir.actions.report"' not in all_content:
        return
    template_ids = set(re.findall(r'<template\b[^>]*\bid="([\w.]+)"', all_content))
    for report_name in re.findall(
        r'<record[^>]*model="ir\.actions\.report"[^>]*>(?:(?!</record>).)*?<field\s+name="report_name">([\w.]+)</field>',
        all_content, re.DOTALL,
    ):
        bare_id = report_name.split(".")[-1]
        if report_name not in template_ids and bare_id not in template_ids:
            raise ValueError(
                f"ir.actions.report's report_name={report_name!r} does not resolve to any "
                f"<template id=...> defined in this module's own generated content."
            )


_TRANSLATABLE_EXCEPTION_CALL_RE = re.compile(r"raise\s+(?:ValidationError|UserError)\(([^)]*)\)")
# A plain, single string literal with NOTHING else in the call argument -- no f/r/b prefix, no
# trailing `% (...)`/`.format(...)`/concatenation. Deliberately a `fullmatch`-shaped pattern
# (anchored both ends against the already-`.strip()`ped argument text), not just a prefix check --
# this is what actually guarantees the f-string/interpolation risk the sibling validator's own
# docstring warns about can never apply here: an f-string always carries its own `f` prefix, and
# any `% (...)`/`.format(...)`/`+`-concatenation tail would leave real, non-quote content after
# the closing quote, which this pattern requires to be completely absent.
_PLAIN_STRING_LITERAL_FULL_RE = re.compile(r"^(['\"])((?:[^\\]|\\.)*?)\1$", re.DOTALL)


def _autofix_wrap_plain_untranslated_error_string_literal(generated: GeneratedModuleFiles) -> None:
    """Real, general fix (2026-08-03, full-30-task sweep, tasks 012/024): the sibling validator
    directly below (`_validate_error_strings_wrapped_in_translate_call`, P11 Tier B item 49) has
    always been deliberately flag-only, for a real, documented reason -- a naive autofix wrapping
    an f-string's own INTERPOLATED RESULT rather than its TEMPLATE would silently make Odoo's own
    `_(...)` translation call worse, not better (it must wrap the format string, never the already-
    substituted text). That real risk is scoped to a genuine subset (f-strings, `%`-formatted or
    `.format()`-built strings) -- confirmed live on 2 separate real tasks the same day that the
    LLM's own actual mistake was always the much simpler, unconditionally-safe case: a single,
    PLAIN string literal with no interpolation at all (`raise ValidationError('The finish date
    cannot be before the start date.')`), where wrapping in `_(...)` is a pure, lossless,
    zero-judgment transformation -- there is no "result vs. template" distinction to get wrong
    when there was never any interpolation to begin with. `_PLAIN_STRING_LITERAL_FULL_RE`'s own
    `fullmatch`-shaped anchoring is what makes this genuinely safe: it only ever fires when the
    ENTIRE call argument (after stripping whitespace) is nothing but one quoted literal, so any
    f-string, `%`-tail, `.format()` call, or concatenation is structurally excluded, never
    guessed at -- exactly preserving the sibling validator's own real caution for every case this
    autofix doesn't confidently handle.
    """
    def _wrap(match: re.Match) -> str:
        call_args = match.group(1)
        stripped = call_args.strip()
        if stripped.startswith("_(") or re.match(r"^[frbFRB]", stripped):
            return match.group(0)
        if not _PLAIN_STRING_LITERAL_FULL_RE.match(stripped):
            return match.group(0)
        return match.group(0).replace(call_args, f"_({stripped})", 1)

    generated.models_py = _TRANSLATABLE_EXCEPTION_CALL_RE.sub(_wrap, generated.models_py)


def _validate_error_strings_wrapped_in_translate_call(generated: GeneratedModuleFiles) -> None:
    """P11 Tier B item 49 (expert design §6.12.1). Flag only, deliberately NOT autofix (the
    addendum's own re-confirmed real risk): a raise ValidationError(...)/UserError(...) call whose
    argument is a plain, un-translated string literal (no _(...) wrap) loses translatability --
    but a naive autofix wrapping an f-string's own RESULT rather than its TEMPLATE would silently
    make it worse (Odoo's _() wraps the format string, not the interpolated result). The sibling
    autofix immediately above now handles the unconditionally-safe plain-literal subset; this
    validator's own raise is the real, remaining safety net for every case that autofix
    deliberately leaves untouched (f-strings, `%`-formatted strings, `.format()` calls) -- let the
    next round's LLM pass correctly distinguish plain strings from f-strings needing the proper
    _("...%s...") % (...) pattern.
    """
    for call_args in _TRANSLATABLE_EXCEPTION_CALL_RE.findall(generated.models_py):
        stripped = call_args.strip()
        if re.match(r"^[frb]?['\"]", stripped) and not stripped.startswith("_("):
            raise ValueError(
                f"raise ValidationError/UserError({call_args.strip()!r}) uses a plain string "
                f"literal, never wrapped in Odoo's own _(...) translation call -- this string "
                f"will never be translated. Wrap the literal TEMPLATE in _(...), never the "
                f"already-interpolated result of an f-string."
            )


_TRANSLATABLE_FIELD_TYPES = {"Char", "Text", "Html", "Selection"}


def _validate_translate_attr_only_on_translatable_types(generated: GeneratedModuleFiles) -> None:
    """P11 Tier B item 50 (expert design §6.12.3). translate=True is only meaningful on
    Char/Text/Html/Selection fields -- Odoo silently ignores it (or raises, version-dependent) on
    any other field type.
    """
    for field_name, field_type in re.findall(
        r"(\w+)\s*=\s*fields\.(\w+)\([^)]*\btranslate\s*=\s*True", generated.models_py,
    ):
        if field_type not in _TRANSLATABLE_FIELD_TYPES:
            raise ValueError(
                f"field {field_name!r} is declared fields.{field_type}(..., translate=True), but "
                f"translate= only has real meaning on {sorted(_TRANSLATABLE_FIELD_TYPES)} fields."
            )


def _validate_rec_name_and_order_reference_real_fields(generated: GeneratedModuleFiles) -> None:
    """P11 Tier B item 51 (expert design §7.2) -- genuinely novel, zero existing coverage
    (confirmed via grep: only the duplicate-special-attr check touches _rec_name/_order, and only
    checks they're assigned once, never that their VALUE names a real field). Same conservative
    "skip on _inherit with unknown base fields" posture as items 7/14/30 above.
    """
    if "_inherit" in generated.models_py:
        return
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    rec_name_match = re.search(r"_rec_name\s*=\s*['\"](\w+)['\"]", generated.models_py)
    if rec_name_match and rec_name_match.group(1) not in declared:
        raise ValueError(
            f"_rec_name = {rec_name_match.group(1)!r} names a field that is not declared anywhere "
            f"on this model -- Odoo raises/falls back silently at registry-build time."
        )
    order_match = re.search(r"_order\s*=\s*['\"]([^'\"]+)['\"]", generated.models_py)
    if order_match:
        for term in order_match.group(1).split(","):
            field_name = re.sub(r"\s+(asc|desc)\s*$", "", term.strip(), flags=re.IGNORECASE)
            if field_name and field_name not in declared:
                raise ValueError(
                    f"_order = {order_match.group(1)!r} references field {field_name!r}, which is "
                    f"not declared anywhere on this model -- Odoo raises a ValueError at "
                    f"registry-build time when an _order field doesn't resolve."
                )


