_IR_CRON_VALID_INTERVAL_TYPES = {"minutes", "hours", "days", "weeks", "months"}


def _validate_ir_cron_interval_type_is_valid_enum(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 78. <field name="interval_type"> must be one of Odoo's real 5
    Selection values -- anything else (e.g. a hallucinated "seconds") is a hard constraint
    violation at record creation.
    """
    for content in (generated.security_xml, *(generated.extra_data_files or {}).values()):
        if not content or 'model="ir.cron"' not in content:
            continue
        for value in re.findall(r'<field\s+name="interval_type">([^<]+)</field>', content):
            if value not in _IR_CRON_VALID_INTERVAL_TYPES:
                raise ValueError(
                    f"ir.cron declares interval_type={value!r}, which is not one of Odoo's real "
                    f"values ({sorted(_IR_CRON_VALID_INTERVAL_TYPES)})."
                )


_VIEW_MODE_VALID_TOKENS = {"tree", "list", "form", "kanban", "calendar", "pivot", "graph", "activity"}
_VIEW_MODE_DEPENDENCY_GATED_TOKENS = {"gantt": "web_gantt", "map": "web_map"}


def _validate_action_view_mode_tokens_are_valid_enum(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 79. Every comma-separated view_mode token must be a real Odoo 16 view
    mode; gantt/map are only valid when their owning module is declared as a manifest dependency.
    """
    for content in (generated.security_xml, generated.views_xml, *(generated.extra_data_files or {}).values()):
        if not content or "ir.actions.act_window" not in content:
            continue
        for view_mode_value in re.findall(r'<field\s+name="view_mode">([^<]+)</field>', content):
            for token in [t.strip() for t in view_mode_value.split(",")]:
                if token in _VIEW_MODE_VALID_TOKENS:
                    continue
                if token in _VIEW_MODE_DEPENDENCY_GATED_TOKENS:
                    owning_module = _VIEW_MODE_DEPENDENCY_GATED_TOKENS[token]
                    if owning_module in (generated.manifest_fields.depends or []):
                        continue
                    raise ValueError(
                        f"view_mode includes {token!r}, which requires the {owning_module!r} "
                        f"module to be declared in the manifest's own depends list -- it is not."
                    )
                raise ValueError(
                    f"view_mode includes {token!r}, which is not a real Odoo 16 view mode token."
                )


def _fields_referenced_in_attrs_and_domain(content: str) -> set[str]:
    """Shared extraction for depth-audit items 80/81/82: every field name referenced inside an
    attrs="{...}"/domain="[...]"/context="{'group_by': '...'}" value anywhere in view content.
    """
    referenced: set[str] = set()
    for attr_value in re.findall(r'(?:attrs|domain)="([^"]*)"', content):
        referenced.update(_DOMAIN_FIELD_NAME_RE.findall(attr_value))
        referenced.update(_UNQUOTED_DOMAIN_FIELD_NAME_RE.findall(attr_value))
    for context_value in re.findall(r'context="([^"]*)"', content):
        referenced.update(re.findall(r"'group_by'\s*:\s*'(\w+)'", context_value))
    for filter_domain in re.findall(r'<filter\b[^>]*\bdomain="([^"]*)"', content):
        referenced.update(_DOMAIN_FIELD_NAME_RE.findall(filter_domain))
        referenced.update(_UNQUOTED_DOMAIN_FIELD_NAME_RE.findall(filter_domain))
    return referenced


def _validate_view_attrs_domain_fields_exist_on_model(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit items 80/81/82 (attrs=/domain=, context group_by=, <filter domain=> all
    share one mechanism -- built as one function). New-model case only (no _inherit) -- can't see
    base-model fields without a live query, same conservative posture as every sibling check.

    Real, confirmed false positive found live (2026-08-15, quick_filter_search_construction):
    the `"_inherit" in generated.models_py` guard only correctly skips a round that edits an
    EXISTING model via a Python `_inherit` class -- but a pure VIEW-ONLY round (e.g. a
    quick-filter search-view override that adds no Python at all) never contains the literal
    string "_inherit" either, since it isn't inheriting anything in Python -- it just leaves
    `models_py` as whatever scaffold boilerplate/commented-out example code was already there,
    which this check then wrongly treated as "the new model's own complete field list",
    guaranteeing every domain field reference looks "missing" regardless of whether it's
    real. Confirmed live twice: `sale.order.user_id` and `product.template.qty_available` both
    genuinely exist (verified directly against the live schema) but were rejected. Fixed with
    the SAME established "does this round genuinely declare a new model in Python"
    signal every sibling check in this file already uses (`_NEW_MODEL_NAME_RE`, a real
    `_name = "..."` assignment) -- this check's own stated scope ("new-model case only")
    literally requires that signal to be present at all, not merely the ABSENCE of "_inherit".
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    if not _NEW_MODEL_NAME_RE.search(generated.models_py):
        return  # no genuinely new model declared this round -- this check has nothing to verify against
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    referenced = _fields_referenced_in_attrs_and_domain(generated.views_xml)
    missing = sorted(referenced - declared)
    if missing:
        raise ValueError(
            f"views_xml's attrs=/domain=/context group_by=/<filter domain=> reference field(s) "
            f"{missing} that are not declared anywhere on this model."
        )


def _validate_test_file_field_refs_exist_on_model(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 85. Third proven instance of the "cross-reference a field name
    against the model's own declaration" bug shape (after views and mail-template Jinja refs),
    applied to tests_py's freehand .create({...})/.write({...}) calls. New-model case only, same
    conservative posture as items 80/81/82.
    """
    if not generated.tests_py or "_inherit" in generated.models_py:
        return
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    for file_name, content in generated.tests_py.items():
        for call_body in re.findall(r"\.(?:create|write)\(\s*\{([^}]*)\}", content):
            for field_name in re.findall(r"['\"](\w+)['\"]\s*:", call_body):
                if field_name not in declared:
                    raise ValueError(
                        f"tests_py[{file_name!r}] calls .create()/.write() with key {field_name!r}, "
                        f"which is not declared anywhere on this model."
                    )


def _validate_no_duplicate_new_model_names_in_same_generation(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 86. A purely local, intra-generation duplicate check -- distinct from
    the two existing live-registry checks (which only catch a collision against an EXTERNAL,
    already-real model, never two `_name=` values colliding with EACH OTHER within this same
    round's own output).
    """
    names = _NEW_MODEL_NAME_RE.findall(generated.models_py)
    counts: dict[str, int] = {}
    for name in names:
        counts[name] = counts.get(name, 0) + 1
    duplicated = sorted(n for n, c in counts.items() if c > 1)
    if duplicated:
        raise ValueError(
            f"generated models_py declares _name = {duplicated} more than once across this same "
            f"generation -- two different classes cannot both define the same new model."
        )


_MAIL_THREAD_RESERVED_FIELDS = {
    "message_follower_ids", "message_ids", "message_partner_ids", "message_main_attachment_id",
    "message_has_error", "message_has_error_counter", "message_attachment_count",
    "message_is_follower", "message_unread", "message_unread_counter", "message_needaction",
    "message_needaction_counter",
}


def _validate_mail_thread_no_field_redeclaration(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 87. Same pattern as Tier B/C items 47/67 (portal.mixin/
    mail.alias.mixin field-redeclaration), applied to mail.thread's own real reserved field set --
    the single highest-real-usage mechanism found across the whole depth-audit program (467,023
    live mail.message rows, per the source document's own graph citation).
    """
    inherits = _inherit_target_names(generated.models_py)
    if "mail.thread" not in inherits:
        return
    redeclared = sorted(set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) & _MAIL_THREAD_RESERVED_FIELDS)
    if redeclared:
        raise ValueError(
            f"this model inherits mail.thread (which already provides {redeclared}), but "
            f"re-declares {redeclared} -- this shadows mail.thread's own real implementation."
        )


async def _autofix_add_mail_thread_inherit_when_tracking_kwarg_used(
    generated: GeneratedModuleFiles, db: str, task_id: str | None = None,
) -> None:
    """Real, confirmed bug found live (2026-08-08, task e89150c8-69de-4cad-8450-69eda822cfcb's
    flagship run, ticket_chatter_logging node): the round's own goal literally requires "every
    state change should be logged to the ticket's own chatter with who did it and when" -- the
    LLM correctly declared `tracking=True` on the state field to get that behavior, but never
    added the one real, required `_inherit = 'mail.thread'` that field kwarg actually depends on
    to do anything at all. `_validate_field_tracking_kwarg_requires_mail_thread_inherit()` below
    correctly, mechanically catches this every time -- but merely catching it, with no
    accompanying autofix, meant this genuinely required, unambiguous fix (there is exactly one
    way to make tracking=True work: inherit mail.thread) escalated straight to a human decision
    after just 1 round, for something with zero real judgment call in it.

    Same shape, same live-target-model false-positive guard, and same conservative posture as the
    sibling `_autofix_add_mail_thread_inherit_when_message_post_used()` immediately above (adding
    'mail.thread' is never unrequested scope creep here -- tracking=True is inert without it, so
    this is the literal, stated deliverable's own dependency, not an invented addition) -- just
    triggered by the `tracking=` kwarg instead of a `message_post(...)` call.
    """
    if not re.search(r"tracking\s*=\s*(?:True|\d+)", generated.models_py):
        return
    inherits = _inherit_target_names(generated.models_py)
    if "mail.thread" in inherits:
        return
    non_mail_targets = [t for t in inherits if t and t != "mail.thread"]
    if non_mail_targets and task_id:
        if is_fast_path_eligible(db):
            from tools_odoo.odoo_schema_client import get_model_fields_fast

            _get_model_fields = get_model_fields_fast
        else:
            _get_model_fields = get_model_fields
        real_fields = await asyncio.to_thread(_get_model_fields, non_mail_targets[0], db)
        if real_fields is not None and "message_follower_ids" in real_fields:
            return  # the target model already provides mail.thread -- adding it again breaks _inherit merging
    list_match = _INHERIT_TARGET_LIST_BLOCK_RE.search(generated.models_py)
    if list_match:
        generated.models_py = (
            generated.models_py[:list_match.end() - 1]
            + ", 'mail.thread'"
            + generated.models_py[list_match.end() - 1:]
        )
        return
    string_match = _INHERIT_TARGET_RE.search(generated.models_py)
    if string_match:
        old = string_match.group(0)
        target = string_match.group(1)
        new = f"_inherit = [{target!r}, 'mail.thread']"
        generated.models_py = generated.models_py.replace(old, new, 1)
        return
    # A brand-new model (`_name=` only, no `_inherit` at all) using tracking= -- unlike the
    # message_post() sibling (which leaves this rarer shape untouched, falling through to its
    # own validator), this trigger's live goal shape (task e89150c8) is EXACTLY a brand-new
    # `_name`-only model, so this case must be handled, not left to escalate. Adds a genuine new
    # `_inherit = ['mail.thread']` line right after the `_name = ...` line.
    name_match = re.search(r"^([ \t]*)_name\s*=\s*['\"][\w.]+['\"]\s*$", generated.models_py, re.MULTILINE)
    if name_match:
        indent = name_match.group(1)
        insertion = f"\n{indent}_inherit = ['mail.thread']"
        insert_at = name_match.end()
        generated.models_py = generated.models_py[:insert_at] + insertion + generated.models_py[insert_at:]


def _validate_field_tracking_kwarg_requires_mail_thread_inherit(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 88. A field declared tracking=True/tracking=<int> on a model NOT
    inheriting mail.thread is inert at best, a write-time error at worst -- a distinct trigger
    (field kwarg, not a message_post(...) call) from Tier B item 45's own scope.
    """
    if not re.search(r"tracking\s*=\s*(?:True|\d+)", generated.models_py):
        return
    if "mail.thread" not in _inherit_target_names(generated.models_py):
        raise ValueError(
            "generated models_py declares a field with tracking=True/tracking=<int>, but this "
            "model does not inherit 'mail.thread' -- field tracking is inert (or a write-time "
            "error) without it."
        )


_TRANSLATE_CALL_RE = re.compile(r'\b_(?:_lt)?\(\s*["\']')
_TRANSLATE_IMPORT_RE = re.compile(r"from\s+odoo(?:\.tools)?\s+import\s+.*\b_(?:lt)?\b")


def _autofix_missing_translation_underscore_import(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 89. Direct structural mirror of the real, shipped
    `_autofix_missing_validation_error_import`: detect `_("...")`/`_lt("...")` usage with no
    corresponding `from odoo import _`/`from odoo.tools import _lt` import. Load-bearing
    genericity guard: `_TRANSLATE_CALL_RE` requires the call to be immediately followed by a
    quote character, avoiding a false-positive on Python's own `for _ in range(3):`/
    `result, _ = foo()` throwaway-variable idiom. Autofix-safe -- an unconditionally-needed import
    addition, the identical zero-judgment class as its sibling.
    """
    if not _TRANSLATE_CALL_RE.search(generated.models_py):
        return
    if _TRANSLATE_IMPORT_RE.search(generated.models_py):
        return
    import_match = re.search(r"^(from odoo import .+)$", generated.models_py, re.MULTILINE)
    if import_match:
        generated.models_py = generated.models_py.replace(
            import_match.group(1), import_match.group(1) + "\nfrom odoo.tools.translate import _", 1,
        )
    else:
        generated.models_py = "from odoo.tools.translate import _\n" + generated.models_py


