def _validate_boolean_required_is_meaningless_noop(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 90. Boolean + required=True is a documented Odoo no-op (a Boolean is
    never "unset," only False) -- advisory. Same "raise but word as a recommendation" convention
    Tier C item 58 already established for this file's other advisory-only findings.
    """
    for field_name in re.findall(r"(\w+)\s*=\s*fields\.Boolean\([^)]*\brequired\s*=\s*True", generated.models_py):
        raise ValueError(
            f"field {field_name!r} is declared fields.Boolean(..., required=True) -- required= is "
            f"a documented no-op on Boolean (it is never \"unset,\" only False); recommended to "
            f"remove required=True, though it causes no real error."
        )


_NUMERIC_GROUP_OPERATOR_VALID = {"sum", "avg", "max", "min", "bool_and", "bool_or", "array_agg", "count", "count_distinct"}


def _validate_numeric_group_operator_is_valid(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 91. group_operator= (Integer/Float/Monetary) must be one of Odoo 16's
    real recognized aggregates.
    """
    for field_type in ("Integer", "Float", "Monetary"):
        for field_name, op in re.findall(
            rf"(\w+)\s*=\s*fields\.{field_type}\([^)]*\bgroup_operator\s*=\s*['\"](\w+)['\"]", generated.models_py,
        ):
            if op not in _NUMERIC_GROUP_OPERATOR_VALID:
                raise ValueError(
                    f"field {field_name!r} declares group_operator={op!r}, which is not one of "
                    f"Odoo 16's real recognized aggregates ({sorted(_NUMERIC_GROUP_OPERATOR_VALID)})."
                )


def _validate_selection_field_default_is_valid_option(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 93. For fields.Selection([...], default='X'), X must be among the
    declared option keys. Skips callable defaults (a bare identifier with no quotes).
    """
    for match in re.finditer(r"fields\.Selection\(\s*\[([^\]]*)\][^)]*\)", generated.models_py):
        options_text = match.group(1)
        full_decl = match.group(0)
        default_match = re.search(r"default\s*=\s*['\"](\w+)['\"]", full_decl)
        if not default_match:
            continue  # no default, or a callable default (bare identifier) -- nothing to check
        default_value = default_match.group(1)
        option_keys = set(re.findall(r"\(\s*['\"](\w+)['\"]", options_text))
        if option_keys and default_value not in option_keys:
            raise ValueError(
                f"fields.Selection(..., default={default_value!r}) is not among the declared "
                f"option keys {sorted(option_keys)} -- Odoo will reject this at record creation."
            )


async def _validate_many2one_comodel_target_exists(
    generated: GeneratedModuleFiles, new_model_names: list[str], db: str, task_id: str | None = None,
) -> None:
    """P11 depth-audit item 95. The deepest real gap in the whole many2one node (4,272 live field
    rows per the source doc's own graph citation) -- confirms a Many2one's own comodel actually
    exists, for any target that isn't one of this round's own new models or a res./ir. well-known
    prefix. Same conservative "skip on uncertainty" posture as every live-query sibling.
    """
    targets = [
        (field_name, comodel)
        for field_name, comodel in re.findall(r"(\w+)\s*=\s*fields\.Many2one\(\s*['\"]([\w.]+)['\"]", generated.models_py)
        if comodel not in new_model_names and comodel.split(".")[0] not in {"res", "ir"}
    ]
    if not targets:
        return
    _get_model_fields = get_model_fields
    if task_id and is_fast_path_eligible(db):
        from tools_odoo.odoo_schema_client import get_model_fields_fast

        _get_model_fields = get_model_fields_fast
    for field_name, comodel in targets:
        real_fields = await asyncio.to_thread(_get_model_fields, comodel, db)
        if real_fields is None:
            continue
        if not real_fields:
            raise ValueError(
                f"field {field_name!r} is declared fields.Many2one({comodel!r}, ...), but "
                f"{comodel!r} does not resolve to a real, live Odoo model."
            )


async def _validate_many2one_domain_kwarg_fields_exist(generated: GeneratedModuleFiles, db: str, task_id: str | None = None) -> None:
    """P11 depth-audit item 96. For a literal-list domain= on a Many2one, confirm referenced field
    names exist on the comodel. Direct structural sibling of _validate_ir_rule_domain_fields_exist.
    Skips string-lambda/expression domains (only a literal [...] list is checked).
    """
    checks: list[tuple[str, str, str]] = []  # (field_name, comodel, domain_text)
    for field_name, comodel, kwargs in re.findall(
        # Allows ONE level of nested parens in the kwargs span (e.g. domain=[(...)]) -- a plain
        # [^)]* here stops at the domain tuple's own inner ')', silently truncating before the
        # real domain_match regex below ever sees a closing ']' -- found and fixed by this
        # item's own test suite before shipping.
        r"(\w+)\s*=\s*fields\.Many2one\(\s*['\"]([\w.]+)['\"]((?:[^()]|\([^()]*\))*)\)", generated.models_py,
    ):
        domain_match = re.search(r"domain\s*=\s*(\[[^\]]*\])", kwargs)
        if domain_match:
            checks.append((field_name, comodel, domain_match.group(1)))
    if not checks:
        return
    _get_model_fields = get_model_fields
    if task_id and is_fast_path_eligible(db):
        from tools_odoo.odoo_schema_client import get_model_fields_fast

        _get_model_fields = get_model_fields_fast
    for field_name, comodel, domain_text in checks:
        real_fields = await asyncio.to_thread(_get_model_fields, comodel, db)
        if real_fields is None:
            continue
        known = set(real_fields) | _WELL_KNOWN_BASE_FIELDS
        referenced = set(_DOMAIN_FIELD_NAME_RE.findall(domain_text)) | set(_UNQUOTED_DOMAIN_FIELD_NAME_RE.findall(domain_text))
        missing = sorted(referenced - known)
        if missing:
            raise ValueError(
                f"field {field_name!r}'s domain={domain_text!r} references field(s) {missing} "
                f"that do not exist on the real comodel {comodel!r}."
            )


_MANY2ONE_ONDELETE_VALID = {"set null", "restrict", "cascade"}


def _validate_many2one_ondelete_value_is_valid_enum(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 97. ondelete= itself must be one of the 3 real values -- orthogonal to
    Tier B item 26's required+ondelete pairing check.
    """
    for field_name, value in re.findall(r"(\w+)\s*=\s*fields\.Many2one\([^)]*\bondelete\s*=\s*['\"]([^'\"]+)['\"]", generated.models_py):
        if value not in _MANY2ONE_ONDELETE_VALID:
            raise ValueError(
                f"field {field_name!r} declares ondelete={value!r}, which is not one of Odoo's "
                f"real values ({sorted(_MANY2ONE_ONDELETE_VALID)})."
            )


