def _validate_precompute_not_combined_with_related(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 103. precompute=True + related=... on the same field is an
    unconditional Odoo 16 constraint violation -- orthogonal to Tier B item 29's store= pairing.
    """
    for match in re.finditer(r"(\w+)\s*=\s*fields\.\w+\(([^)]*)\)", generated.models_py):
        kwargs = match.group(2)
        if "precompute=True" in kwargs.replace(" ", "") and "related=" in kwargs:
            raise ValueError(
                f"field {match.group(1)!r} combines precompute=True with related=... -- an "
                f"unconditional Odoo 16 constraint violation; precompute is only for compute=."
            )


async def _validate_related_field_type_matches_target_field_type(generated: GeneratedModuleFiles, db: str, task_id: str | None = None) -> None:
    """P11 depth-audit item 104 -- honest, documented no-op, same category as base-tier items
    42/43/66. Checked directly before building anything: `get_model_fields()`/`get_model_fields_
    fast()` (the only live-registry field tools this codebase has) return `list[str]` -- field
    NAMES only, no type information at all -- and no type-aware variant exists anywhere in
    `tools_odoo/`. This item's own real requirement ("compare the target field's live TYPE against
    the related= field's own declared type") is genuinely not buildable with current tooling, a
    real infra gap, not a design choice. Kept as a real, named, async function (matching this
    item's own intended signature) rather than deleted, so its build-list slot is honestly closed
    and immediately buildable the moment a type-aware live-field-lookup tool exists.
    """
    return


_FIELD_DECL_WITH_TYPE_AND_KWARGS_RE = re.compile(r"(\w+)\s*=\s*fields\.(\w+)\(([^)]*)\)")
_NO_REAL_COLUMN_FIELD_TYPES = {"One2many", "Many2many"}


def _validate_sql_constraint_referenced_fields_exist(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 105. For the common unique(...)/check(...) shapes, confirm every
    referenced identifier is a real declared field. Deliberately conservative -- skips any SQL
    text this simple regex can't confidently parse.

    P11 fifth pass item 180 (docs/planning/PHASE30_SECOND_PASS_FINAL_CONSOLIDATED_2026-07-30.md
    §1.3): extended in place (not a new sibling -- this item's own text calls it "a depth
    extension of item 105's own scope"), reusing item 105's own extraction. For every field
    referenced inside a unique(...)/check(...) clause, cross-references the field's own
    declaration: a One2many/Many2many (no real scalar column at all) or a `compute=`d field with
    no `store=True` (no real, persisted column either) both make `ALTER TABLE ... ADD CONSTRAINT`
    fail with a real `UndefinedColumn` error at install. Conservative, matching item 105's own
    posture: only flags a field whose declaration this simple single-line regex can confidently
    parse and classify -- a multi-line declaration, or a bare `related=` field, is skipped rather
    than guessed at.
    """
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    if "_inherit" in generated.models_py:
        return
    field_decls = {
        name: (ftype, kwargs)
        for name, ftype, kwargs in _FIELD_DECL_WITH_TYPE_AND_KWARGS_RE.findall(generated.models_py)
    }
    for block_match in re.finditer(r"_sql_constraints\s*=\s*\[(.*?)\]", generated.models_py, re.DOTALL):
        for sql_text in re.findall(r"\(\s*['\"][\w]+['\"]\s*,\s*['\"]((?:unique|check)\([^)]*\))['\"]", block_match.group(1)):
            fields_in_sql = re.findall(r"\((\w+(?:\s*,\s*\w+)*)\)", sql_text)
            for group in fields_in_sql:
                for field_name in [f.strip() for f in group.split(",")]:
                    if not field_name:
                        continue
                    if field_name not in declared:
                        raise ValueError(
                            f"_sql_constraints references field {field_name!r} in {sql_text!r}, "
                            f"which is not declared anywhere on this model."
                        )
                    decl = field_decls.get(field_name)
                    if decl is None:
                        continue  # a real field, but this simple regex couldn't confidently parse
                        # its own declaration (e.g. multi-line) -- skip rather than guess.
                    ftype, kwargs = decl
                    if ftype in _NO_REAL_COLUMN_FIELD_TYPES:
                        raise ValueError(
                            f"_sql_constraints references field {field_name!r} in {sql_text!r}, but "
                            f"{field_name!r} is declared fields.{ftype}(...) -- a {ftype} field has "
                            f"no real scalar database column at all, so ALTER TABLE ADD CONSTRAINT "
                            f"will fail with UndefinedColumn at install."
                        )
                    if "compute=" in kwargs and "store=True" not in kwargs:
                        raise ValueError(
                            f"_sql_constraints references field {field_name!r} in {sql_text!r}, but "
                            f"{field_name!r} is a compute= field with no store=True -- it has no real, "
                            f"persisted database column, so ALTER TABLE ADD CONSTRAINT will fail with "
                            f"UndefinedColumn at install."
                        )


def _validate_api_constrains_method_has_a_raise(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 106. Every @api.constrains(...)-decorated method must contain at least
    one raise somewhere in its body -- a pure structural-absence check, orthogonal to Tier A item
    14's field-existence check.

    Real, confirmed bug found live (2026-08-03, task012's own real re-test, 3 identical false
    positives in a row): the body-capture group required EVERY line, including the method's own
    final line, to end in a real `\\n` (`[ \\t]+.*\\n`) -- but `generated.models_py` genuinely has
    no trailing newline after its own last line (confirmed via a direct `repr()` of the real,
    live content: the file's final character is the closing `)` of the `raise` statement, not a
    newline). Whenever the `raise` happened to be the method's own (and the whole file's own)
    final line, the unterminated last line silently failed the `\\n`-required pattern and dropped
    out of the captured body entirely -- a real false positive on a method that DOES raise,
    exactly matching what task012 correctly wrote every single time. Fixed by making the trailing
    newline optional on the per-line alternative (`\\n?` instead of `\\n`), which still matches
    every properly-terminated non-final line exactly as before and now also matches a final line
    that happens to end the string with no newline at all.
    """
    for match in re.finditer(
        r"@api\.constrains\([^)]*\)\s*\n\s*def\s+(\w+)\s*\(self\)[^:]*:\n((?:[ \t]+.*\n?|\n)*)",
        generated.models_py,
    ):
        method_name, body = match.group(1), match.group(2)
        if "raise" not in body:
            raise ValueError(
                f"@api.constrains-decorated method {method_name!r} has no raise anywhere in its "
                f"body -- a constraint check that never raises can never actually enforce anything."
            )


def _validate_persisted_model_declares_name_or_inherit(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 107. A models.Model subclass with neither _name nor _inherit has no
    real identity at all -- Odoo raises directly.
    """
    for block_match in _MODEL_CLASS_BLOCK_RE.finditer(generated.models_py):
        block = block_match.group(0)
        if not re.search(r"_name\s*=", block) and not re.search(r"_inherit\s*=", block):
            class_name_match = re.match(r"^class\s+(\w+)", block)
            raise ValueError(
                f"class {class_name_match.group(1) if class_name_match else '(unknown)'!r} "
                f"(models.Model) declares neither _name nor _inherit -- it has no real model "
                f"identity at all; Odoo raises directly at registry-build time."
            )


def _validate_abstract_model_not_granted_security_csv_access(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 108. Cross-references security_csv model_id:id rows against classes
    whose real base includes models.AbstractModel -- same underlying fact as Tier B item 32,
    different artifact (CSV rows, not XML data records).
    """
    abstract_models = set(re.findall(
        r"class\s+\w+\(models\.AbstractModel\):.*?_name\s*=\s*['\"]([\w.]+)['\"]",
        generated.models_py, re.DOTALL,
    ))
    if not abstract_models or not generated.security_csv:
        return
    for line in generated.security_csv.splitlines()[1:]:
        cols = line.split(",")
        if len(cols) < 3:
            continue
        model_ref = cols[2].strip()
        bare_model = model_ref.split(".")[-1].removeprefix("model_").replace("_", ".")
        for abstract_model in abstract_models:
            if bare_model == abstract_model or model_ref == f"model_{abstract_model.replace('.', '_')}":
                raise ValueError(
                    f"security_csv grants access to {model_ref!r}, but that resolves to "
                    f"{abstract_model!r}, an AbstractModel -- AbstractModel records are never "
                    f"directly accessible, granting CSV access to one is meaningless."
                )


def _validate_kanban_view_has_required_template_scaffold(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 112. A Kanban <record> missing the <templates><t t-name="kanban-box">
    wrapper is a hard ParseError.
    """
    if not generated.views_xml or "<kanban" not in generated.views_xml:
        return
    for kanban_match in re.finditer(r"<kanban\b[^>]*>(.*?)</kanban>", generated.views_xml, re.DOTALL):
        block = kanban_match.group(1)
        if "<templates" not in block or 't-name="kanban-box"' not in block:
            raise ValueError(
                "a <kanban> view is missing the required <templates><t t-name=\"kanban-box\"> "
                "wrapper -- Odoo raises a hard ParseError without it."
            )


_VIEW_MODE_TO_OWNING_MODULE = {"gantt": "web_gantt", "grid": "web_grid", "map": "base_geolocalize"}


def _validate_gantt_grid_map_view_declares_owning_module_dependency(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 113. A Gantt/Grid/Map view without its real owning module in depends=
    is a guaranteed install crash.
    """
    if not generated.views_xml:
        return
    depends = set(generated.manifest_fields.depends or [])
    for tag, owning_module in _VIEW_MODE_TO_OWNING_MODULE.items():
        if f"<{tag}" in generated.views_xml and owning_module not in depends:
            raise ValueError(
                f"views_xml declares a <{tag}> view, but the manifest's own depends list does "
                f"not include {owning_module!r} -- Odoo raises a guaranteed install crash without it."
            )


def _validate_xpath_by_field_name_target_exists_on_model(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 114. For <xpath expr="//field[@name='X']">, confirm X exists on the
    model -- a weaker but real, zero-live-query, cheap partial substitute for full xpath resolution.
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    for field_name in re.findall(r'<xpath\b[^>]*\bexpr="//field\[@name=\'(\w+)\'\]"', generated.views_xml):
        if field_name not in declared:
            raise ValueError(
                f"<xpath expr=\"//field[@name='{field_name}']\"> targets a field that is not "
                f"declared anywhere on this model."
            )


def _validate_smart_button_statinfo_field_is_numeric(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 115. A widget="statinfo" field should back an Integer/Float field --
    direct precedent (currency_field type-compatibility, Tier B item 25).
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    numeric_fields = dict(re.findall(r"(\w+)\s*=\s*fields\.(Integer|Float)\(", generated.models_py))
    for field_name in re.findall(r'<field\s+name="(\w+)"\s+widget="statinfo"', generated.views_xml):
        if field_name in dict(re.findall(r"(\w+)\s*=\s*fields\.(\w+)\(", generated.models_py)) and field_name not in numeric_fields:
            raise ValueError(
                f"<field name=\"{field_name}\" widget=\"statinfo\"> should back an Integer/Float "
                f"field, but it is declared as a different type."
            )


def _validate_stat_button_uses_button_box_placement(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 116. A validator counterpart to the existing autofix's own generation-
    side placement rule, for the LLM-hand-authored path: a widget="statinfo" stat button must sit
    inside a <div class="oe_button_box">.
    """
    if not generated.views_xml or 'widget="statinfo"' not in generated.views_xml:
        return
    for form_match in re.finditer(r"<form\b[^>]*>(.*?)</form>", generated.views_xml, re.DOTALL):
        block = form_match.group(1)
        for button_match in re.finditer(r'<button\b[^>]*widget="statinfo"[^>]*/?>', block):
            preceding = block[:button_match.start()]
            last_button_box_open = preceding.rfind('class="oe_button_box"')
            last_button_box_close = preceding.rfind("</div>")
            if last_button_box_open == -1 or last_button_box_open < last_button_box_close:
                raise ValueError(
                    "a widget=\"statinfo\" stat button is not placed inside a "
                    "<div class=\"oe_button_box\"> -- Odoo's own smart-button placement convention."
                )


def _validate_statusbar_visible_values_are_real_selection_options(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 117. statusbar_visible="draft,confirmed,done" values should be a
    subset of the target field's real Selection options.
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    for field_name, visible_value in re.findall(
        r'<field\s+name="(\w+)"[^>]*\bstatusbar_visible="([^"]*)"', generated.views_xml,
    ):
        decl_match = re.search(rf"{re.escape(field_name)}\s*=\s*fields\.Selection\(\s*\[([^\]]*)\]", generated.models_py)
        if not decl_match:
            continue
        option_keys = set(re.findall(r"\(\s*['\"](\w+)['\"]", decl_match.group(1)))
        visible_tokens = {t.strip() for t in visible_value.split(",") if t.strip()}
        missing = sorted(visible_tokens - option_keys)
        if option_keys and missing:
            raise ValueError(
                f"statusbar_visible on field {field_name!r} names value(s) {missing} that are "
                f"not among its own real Selection options {sorted(option_keys)}."
            )


_COMMON_WIDGET_FIELD_TYPE_MAP = {
    "many2one_avatar": "Many2one", "priority": "Selection", "boolean_toggle": "Boolean",
    "percentpie": ("Integer", "Float"), "monetary": "Monetary",
}


def _validate_common_widget_field_type_compatibility(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 118. Small, hardcoded, version-stable {widget: expected_type} map,
    deliberately limited to universally-stable Odoo-core widgets -- NOT blocked by Tier B item 38's
    deployment-specific full-widget-allowlist prerequisite, since this is a much narrower set.
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    field_types = dict(re.findall(r"(\w+)\s*=\s*fields\.(\w+)\(", generated.models_py))
    for field_name, widget in re.findall(r'<field\s+name="(\w+)"[^>]*\bwidget="(\w+)"', generated.views_xml):
        expected = _COMMON_WIDGET_FIELD_TYPE_MAP.get(widget)
        if expected is None or field_name not in field_types:
            continue
        expected_types = expected if isinstance(expected, tuple) else (expected,)
        if field_types[field_name] not in expected_types:
            raise ValueError(
                f"<field name=\"{field_name}\" widget=\"{widget}\"> expects a "
                f"{'/'.join(expected_types)} field, but it is declared as {field_types[field_name]!r}."
            )


_BOOTSTRAP_DECORATION_CLASSES = {"danger", "warning", "info", "success", "muted", "primary", "secondary"}


def _validate_decoration_class_is_real_bootstrap_context(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 119. decoration-* class name is a small, version-independent
    Bootstrap-defined closed set -- a hallucinated class silently renders unstyled.
    """
    if not generated.views_xml:
        return
    for cls in re.findall(r"decoration-(\w+)=", generated.views_xml):
        if cls not in _BOOTSTRAP_DECORATION_CLASSES:
            raise ValueError(
                f"decoration-{cls}= is not one of Odoo's real Bootstrap-defined decoration "
                f"classes ({sorted(_BOOTSTRAP_DECORATION_CLASSES)}) -- it will silently render unstyled."
            )


def _validate_decoration_condition_value_matches_selection_options(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 120. When a decoration-* condition's compared field is Selection-typed,
    the compared literal should be a real option value.
    """
    if not generated.views_xml or "_inherit" in generated.models_py:
        return
    for expr in _DECORATION_ATTR_RE.findall(generated.views_xml):
        field_match = re.match(r"\s*(\w+)\s*==\s*['\"](\w+)['\"]", expr)
        if not field_match:
            continue
        field_name, literal = field_match.group(1), field_match.group(2)
        decl_match = re.search(rf"{re.escape(field_name)}\s*=\s*fields\.Selection\(\s*\[([^\]]*)\]", generated.models_py)
        if not decl_match:
            continue
        option_keys = set(re.findall(r"\(\s*['\"](\w+)['\"]", decl_match.group(1)))
        if option_keys and literal not in option_keys:
            raise ValueError(
                f"a decoration-* condition compares Selection field {field_name!r} to "
                f"{literal!r}, which is not among its own real option keys {sorted(option_keys)}."
            )


async def _validate_action_res_model_is_real_or_declared(generated: GeneratedModuleFiles, db: str, task_id: str | None = None) -> None:
    """P11 depth-audit item 121. For ir.actions.act_window's res_model, confirm it's a new-this-
    round model, the _inherit target, or a live-confirmed real model.
    """
    if not generated.views_xml:
        return
    new_model_names = set(_NEW_MODEL_NAME_RE.findall(generated.models_py))
    inherit_names = set(_inherit_target_names(generated.models_py))
    known_locally = new_model_names | inherit_names
    for res_model in _XML_ACTION_RES_MODEL_RE.findall(generated.views_xml):
        if res_model in known_locally or res_model.split(".")[0] in {"res", "ir"}:
            continue
        if task_id and is_fast_path_eligible(db):
            from tools_odoo.odoo_schema_client import get_model_fields_fast

            real_fields = await asyncio.to_thread(get_model_fields_fast, res_model, db)
        else:
            real_fields = await asyncio.to_thread(get_model_fields, res_model, db)
        if real_fields is None:
            continue
        if not real_fields:
            raise ValueError(
                f"ir.actions.act_window's res_model={res_model!r} does not resolve to a real, "
                f"live Odoo model, and is not one of this round's own new/inherited models."
            )


def _validate_server_action_code_does_not_reference_undefined_self(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 122. ir.actions.server's state="code" eval context does not provide
    self (unlike ordinary Odoo method bodies) -- direct in-file precedent
    (_autofix_ir_cron_deprecated_function_field fixes the identical class for a different context).
    """
    for content in (generated.security_xml, *(generated.extra_data_files or {}).values()):
        if not content or 'model="ir.actions.server"' not in content:
            continue
        for block in re.findall(
            r'<record[^>]*model="ir\.actions\.server"[^>]*>(?:(?!</record>).)*?</record>', content, re.DOTALL,
        ):
            if '<field name="state">code</field>' not in block:
                continue
            code_match = re.search(r'<field\s+name="code">([^<]*)</field>', block)
            if code_match and re.search(r"\bself\.", code_match.group(1)):
                raise ValueError(
                    "an ir.actions.server record with state=\"code\" references self.* in its own "
                    "code field -- unlike an ordinary Odoo method body, this eval context does not "
                    "provide self; use model/record/env instead."
                )


def _validate_no_base_automation_model_reference(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 124. Explicitly deployment-fact-dependent: this project's real target
    instance has base_automation confirmed NOT installed -- any model="base.automation"/
    model="base_automation" reference is guaranteed to crash. Revisit if that ever changes.
    """
    for content in (generated.security_xml, generated.views_xml, *(generated.extra_data_files or {}).values()):
        if content and re.search(r'model="base[._]automation"', content):
            raise ValueError(
                "generated content references model=\"base.automation\"/\"base_automation\" -- "
                "this project's real target instance has confirmed this module is NOT installed; "
                "this reference is guaranteed to crash at install time."
            )


def _validate_test_methods_contain_at_least_one_assertion(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 125. A test method with zero assert*/self.assertRaises/self.assertEqual
    -shaped calls always "passes" regardless of correctness. Only relevant to the LLM-freehand test
    path.
    """
    if not generated.tests_py:
        return
    for file_name, content in generated.tests_py.items():
        # _TEST_METHOD_SPLIT_RE is a zero-width split immediately BEFORE each `def test_` line --
        # re.split's own defined behavior means each part in parts[1:] is already exactly one
        # method's own full body, from its own def line up to (not including) the next split
        # point (or EOF) -- no further "find the next def" slicing needed (an earlier version of
        # this function did that redundantly, and buggily -- part[1:] sliced off only the first
        # CHARACTER, not the first LINE, immediately re-matching the same def line and truncating
        # the body before it ever reached the method's own real assertion; found and fixed by
        # this item's own test suite before shipping).
        parts = _TEST_METHOD_SPLIT_RE.split(content)
        for body in parts[1:]:
            method_name_match = re.match(r"[ \t]*def\s+(test_\w+)", body)
            if not method_name_match:
                continue
            if not re.search(r"\bself\.assert\w*\(|\bassert\s+", body):
                raise ValueError(
                    f"tests_py[{file_name!r}]'s {method_name_match.group(1)!r} has no "
                    f"assert*/self.assertX() call anywhere in its body -- it always \"passes\" "
                    f"regardless of correctness."
                )


def _validate_test_classes_have_tagged_decorator(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 126. A freehand test class missing @tagged(...) may run before
    cross-model dependency data is loaded -- a real, second-order Odoo test-runner correctness risk.
    """
    if not generated.tests_py:
        return
    for file_name, content in generated.tests_py.items():
        for class_match in re.finditer(r"(^@tagged\([^)]*\)\n)?^class\s+(\w+)\([^)]*Case\)", content, re.MULTILINE):
            if not class_match.group(1):
                raise ValueError(
                    f"tests_py[{file_name!r}]'s class {class_match.group(2)!r} has no @tagged(...) "
                    f"decorator -- may run before cross-model dependency data is loaded."
                )


def _validate_security_csv_perm_columns_are_binary(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 127. Every perm_read/perm_write/perm_create/perm_unlink cell must be
    exactly "0" or "1" -- Odoo's CSV boolean coercion is inconsistent for other truthy-looking
    strings.
    """
    lines = [l for l in (generated.security_csv or "").splitlines() if l.strip()]
    if len(lines) <= 1:
        return
    for line in lines[1:]:
        cols = line.split(",")
        if len(cols) < 8:
            continue
        for col in cols[4:8]:
            if col.strip() not in ("0", "1"):
                raise ValueError(
                    f"security_csv row has a perm_* column value {col.strip()!r} that is not "
                    f"exactly '0' or '1' -- Odoo's own CSV boolean coercion is inconsistent for "
                    f"any other value."
                )


async def _validate_security_csv_model_id_refers_to_known_model(generated: GeneratedModuleFiles, db: str, task_id: str | None = None) -> None:
    """P11 depth-audit item 129. Mirror of the already-shipped
    _validate_security_csv_group_id_refers_to_a_defined_group, applied to the model_id:id column's
    REVERSE direction: does each row's model reference resolve, not just "does every new model
    have a row."
    """
    lines = [l for l in (generated.security_csv or "").splitlines() if l.strip()]
    if len(lines) <= 1:
        return
    new_model_names = set(_NEW_MODEL_NAME_RE.findall(generated.models_py))
    new_model_bare_ids = {f"model_{m.replace('.', '_')}" for m in new_model_names}
    for line in lines[1:]:
        cols = line.split(",")
        if len(cols) < 3:
            continue
        model_ref = cols[2].strip()
        bare_ref = model_ref.split(".")[-1]
        if bare_ref in new_model_bare_ids:
            continue  # this round's own new model -- not yet in the live registry, correctly skipped
        if task_id and is_fast_path_eligible(db):
            from tools_odoo.odoo_schema_client import resolve_xmlids_exist_fast

            resolved = await asyncio.to_thread(resolve_xmlids_exist_fast, [model_ref], db)
        else:
            resolved = await asyncio.to_thread(resolve_xmlids_exist, [model_ref], db)
        if resolved is None:
            continue
        if not resolved.get(model_ref, False):
            raise ValueError(
                f"security_csv row references model_id:id={model_ref!r}, which does not resolve "
                f"to a real external id in the live registry."
            )


def _validate_qweb_report_action_report_name_matches_template_id(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 130. ir.actions.report's report_name is a free-text field value,
    invisible to every existing xmlid-resolution check; cross-reference against locally-defined
    <template id="..."> values. Same real resolution logic as Tier B item 48/Tier C item 65 --
    kept as its own item since the source doc lists it separately.
    """
    _validate_qweb_report_template_id_resolves(generated)


def _validate_qweb_report_field_references_exist_on_model(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 131. QWeb t-field="doc.X"/t-esc="doc.X" references are invisible to
    _validate_view_fields_exist_on_model's element-only regex -- the single highest-value new
    proposal in the whole Reporting section (silently blank/crashes only deep in QWeb's own render
    pipeline, the first time a real user opens the report). Load-bearing genericity guard: scoped
    strictly to the doc. prefix (Odoo's own standard report-context variable), never o/company/user.
    """
    if "_inherit" in generated.models_py:
        return
    declared = set(_MODEL_FIELD_DEF_RE.findall(generated.models_py)) | _WELL_KNOWN_BASE_FIELDS
    for content in (generated.security_xml, *(generated.extra_data_files or {}).values()):
        if not content or "<template" not in content:
            continue
        for field_name in re.findall(r't-(?:field|esc)="doc\.(\w+)"', content):
            if field_name not in declared:
                raise ValueError(
                    f"a QWeb report template references doc.{field_name}, which is not declared "
                    f"anywhere on this model -- will render silently blank or crash only when a "
                    f"real user opens the report."
                )


