def _autofix_security_csv_perm_unlink_defaults_to_zero(generated: GeneratedModuleFiles, goal: str) -> None:
    """Real, confirmed bug found live (2026-08-03, task010's own real, repeated stall): this
    project's own deterministic security_csv builder (build_deterministic_security_csv above)
    already encodes perm_unlink=0 as the non-negotiable default unless the goal explicitly asks
    for delete capability -- but that policy only ever applied to the deterministic builder's OWN
    output. Whenever that builder defers to the LLM (e.g. `_maybe_override_security_csv_
    deterministically`'s new-custom-group-for-an-existing-model case), the LLM's own freeform
    security_csv routinely set perm_unlink=1 with no goal signal requesting it, and nothing ever
    corrected it back down -- `_validate_security_csv_perm_unlink_matches_goal_intent` below only
    ever flagged it as an advisory ValueError, burning a full round to ask Build to fix something
    this project already has a clear, established, deterministic default answer for. Confirmed
    live: task010 stalled for 2 full rounds re-generating the exact same perm_unlink=1 mistake
    before this fix, using the SAME conservative delete/unlink/remov* goal-intent check the
    advisory validator itself already uses, so this can never silently override a genuine explicit
    delete request.
    """
    if re.search(r"\b(delete|unlink|remov\w*)\b", goal or "", re.IGNORECASE):
        return
    lines = (generated.security_csv or "").splitlines()
    if not lines:
        return
    changed = False
    new_lines = [lines[0]]
    for line in lines[1:]:
        if not line.strip():
            new_lines.append(line)
            continue
        cols = line.split(",")
        if len(cols) >= 8 and cols[7].strip() == "1":
            cols[7] = "0"
            line = ",".join(cols)
            changed = True
        new_lines.append(line)
    if changed:
        generated.security_csv = "\n".join(new_lines)


def _validate_security_csv_perm_unlink_matches_goal_intent(generated: GeneratedModuleFiles, goal: str) -> None:
    """P11 depth-audit item 162. Flag-only, advisory, explicitly a soft judgment call (lower-
    confidence than the other security items) -- a goal can legitimately want delete capability
    without using those literal words, so this is a recommendation, not a hard requirement. The
    common, deterministic case (no delete intent at all in the goal) is now auto-corrected by
    `_autofix_security_csv_perm_unlink_defaults_to_zero` above, called before this; this remains
    as a safety net for any shape that autofix doesn't touch (e.g. perm_unlink already 0, or a
    genuinely ambiguous partial delete-adjacent phrasing the autofix's own conservative regex
    doesn't match).
    """
    if re.search(r"\b(delete|unlink|remov\w*)\b", goal or "", re.IGNORECASE):
        return
    lines = [l for l in (generated.security_csv or "").splitlines() if l.strip() and not l.startswith("id,")]
    for line in lines:
        cols = line.split(",")
        if len(cols) >= 8 and cols[7].strip() == "1":
            raise ValueError(
                f"security_csv grants perm_unlink=1, but the goal text doesn't mention delete/"
                f"unlink/removal -- recommended to double-check this is genuinely intended, not a "
                f"hard requirement (a goal can legitimately want delete capability unstated)."
            )


_COMPANY_RESTRICTION_GOAL_RE = re.compile(r"\b(multi-?company|per[- ]company|company[- ]specific|only see .* company)\b", re.IGNORECASE)


def _validate_goal_named_company_restriction_is_implemented(generated: GeneratedModuleFiles, goal: str, goal_facts: dict | None = None) -> None:
    """P11 depth-audit item 163 -- extends Tier C items 72/73's own "goal-named-X-is-implemented"
    family to company_rules (multi-company visibility scoping). Flag-only, same rationale.
    """
    if not _COMPANY_RESTRICTION_GOAL_RE.search(goal or ""):
        return
    if not generated.security_xml or "ir.rule" not in generated.security_xml:
        raise ValueError(
            "the goal explicitly requests company-scoped visibility, but generated security_xml "
            "declares no ir.rule record at all -- this requirement has not actually been implemented."
        )
    rule_blocks = re.findall(r'<record[^>]*model="ir\.rule"[^>]*>(?:(?!</record>).)*?</record>', generated.security_xml, re.DOTALL)
    if not any("company_id" in block for block in rule_blocks):
        raise ValueError(
            "the goal explicitly requests company-scoped visibility, and an ir.rule record "
            "exists, but none of its domain(s) reference company_id."
        )


_ODOO_TARGET_SERIES = "16.0."


def _autofix_manifest_version_prefixed_with_odoo_series(generated: GeneratedModuleFiles) -> None:
    """P14 item 2 benchmark finding (2026-08-02, docs/reports/PHASE30_P14_ITEM2_BENCHMARK_2026-08-02.md
    re-run): after fixing the security_csv-for-custom-groups gap, this became the single most
    common remaining blocker in a 12-task representative benchmark (5 of 12: tasks 008/010/028/
    029/030) -- Build consistently writes a bare semver like '1.0.0' with no Odoo series prefix at
    all. Zero judgment call, unlike the sibling flag-only validator's own conservative "just flag
    it" posture might suggest: there is exactly one correct target series for this project
    (`_ODOO_TARGET_SERIES`), and prepending it to whatever version string Build already wrote is
    always strictly more correct than leaving a bare semver in place -- never invents a version
    number, only prefixes the one that's already there.
    """
    version = generated.manifest_fields.version
    if version and not version.startswith(_ODOO_TARGET_SERIES):
        generated.manifest_fields.version = f"{_ODOO_TARGET_SERIES}{version}"


def _validate_manifest_version_matches_odoo_series(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 164. version should at least start with the project's real target
    series (16.0.). Low severity (breaks only Apps-list display and upgrade tooling, not install).

    In practice this should no longer fire -- 2026-08-02's
    `_autofix_manifest_version_prefixed_with_odoo_series` (called earlier in the chain) self-heals
    the exact shape this validator flags. Left in place as a backstop for any shape that autofix
    doesn't cover (there currently is none, but future manifest-building paths may bypass it).
    """
    version = generated.manifest_fields.version
    if version and not version.startswith(_ODOO_TARGET_SERIES):
        raise ValueError(
            f"manifest version={version!r} does not start with '16.0.' (this project's real "
            f"target Odoo series) -- breaks Apps-list display/upgrade tooling, though not install."
        )


def _autofix_manifest_removes_self_dependency(generated: GeneratedModuleFiles, module_name: str) -> None:
    """P11 depth-audit item 165. Deterministic, zero-judgment: strip the module's own name from
    depends if present.
    """
    if module_name in (generated.manifest_fields.depends or []):
        generated.manifest_fields.depends = [d for d in generated.manifest_fields.depends if d != module_name]


def _validate_custom_report_model_get_report_values_shape(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 166. Flag-only; a _get_report_values override missing a super() call
    loses the base implementation's own context keys. Deliberately does not check the returned
    dict's exact keys (version-drift risk) -- the super()-presence check alone is the
    zero-judgment slice.
    """
    method_match = re.search(r"def\s+_get_report_values\s*\(self[^)]*\)[^:]*:\n((?:[ \t]+.*\n|\n)*)", generated.models_py)
    if method_match and "super(" not in method_match.group(1):
        raise ValueError(
            "_get_report_values(...) is overridden but never calls super() -- this loses the "
            "base implementation's own real context keys (doc_ids, doc_model, etc.)."
        )


def _validate_paperformat_custom_format_requires_dimensions(generated: GeneratedModuleFiles) -> None:
    """P11 depth-audit item 167 -- extends Tier C item 68. When format == 'custom', page_width/
    page_height become functionally required (Odoo falls back to invalid dimensions otherwise, a
    visibly broken PDF, not a crash).
    """
    for content in (generated.security_xml, *(generated.extra_data_files or {}).values()):
        if not content or 'model="report.paperformat"' not in content:
            continue
        for block in re.findall(r'<record[^>]*model="report\.paperformat"[^>]*>(?:(?!</record>).)*?</record>', content, re.DOTALL):
            if '<field name="format">custom</field>' not in block:
                continue
            if '<field name="page_width"' not in block or '<field name="page_height"' not in block:
                raise ValueError(
                    "report.paperformat declares format='custom' but is missing page_width/"
                    "page_height -- Odoo falls back to invalid dimensions, a visibly broken PDF."
                )



# ============================================================================
# Phase T (§24 of PHASE30_OMA_SEAM_COVERAGE_AND_COMBINATORIAL_HARDENING_2026-
# 07-29.md) -- a bounded, in-round Agent-Computer Interface (ACI) and internal
# check/revise loop for Build, nested INSIDE each existing external round.
#
# Scope, restated from §24.4 (do not widen without re-reading that section):
# additive to Build's own internal process only. Does NOT touch the 5-round
# external structure, is_known_repeat(), Code-Review, Testing/QA, the whole-
# assembly install check, cloud escalation, or the `data_change` capability
# gate. The narrow validator subset below reuses real, already-tested
# functions from this same file -- no new verification logic is added here,
# only earlier, in-model access to checks that already existed.
# ============================================================================

# §24.2.2: "2-4 internal check-revise cycles... more than 4 is very unlikely
# to be worth the added cost." §24.5 explicitly says to start at the low end
# of that range and measure before widening it -- this is the low end, not a
# placeholder.
MAX_INTERNAL_LOOP_STEPS = 2

# §24.2.2 asks for a real cost cap "tracked independently of step count,"
# reusing the exact enforcement SHAPE infra/cloud_escalation.py already
# established for its own per-task dollar ceiling. Local-backend calls (the
# ones this internal loop makes) have no real $ cost tracked anywhere in this
# codebase -- only infra/cloud_escalation.py's cloud-tier calls do. The
# honest local equivalent of "cost" is real wall-clock duration, the same
# resource ModelGatewayClient.pop_call_stats() already accounts for per task
# (Phase 30, P1d) -- so this is a genuine second, independent budget (time),
# not a step count in disguise, using this codebase's own already-real
# accounting instead of inventing a fictional dollar figure for calls nothing
# else here bills.
MAX_INTERNAL_LOOP_DURATION_SEC = 60.0

# §24.2.1: "a small, fast, high-signal subset (the ones most often catching
# Build's own known mistake shapes, per today's real 30-task-sweep data:
# duplicate _name/method definitions, security_csv shape, _inherit/
# mail.thread checks)." Every one of these is a real, already-existing,
# already-tested function defined earlier in this same file -- reused
# verbatim, never duplicated.
_INTERNAL_LOOP_NARROW_VALIDATORS: list[tuple[str, "Callable[[GeneratedModuleFiles], None]"]] = [
    ("generated_python_files_are_valid_syntax", _validate_generated_python_files_are_valid_syntax),
    ("no_bare_import_of_odoo_names", _validate_no_bare_import_of_odoo_names),
    ("no_direct_inherit_extension_of_res_groups", _validate_no_direct_inherit_extension_of_res_groups),
    ("no_stdlib_datetime_now_for_date_comparisons", _validate_no_stdlib_datetime_now_for_date_comparisons),
    ("no_duplicate_method_definitions", _validate_no_duplicate_method_definitions),
    ("security_csv_row_column_count_matches_header", _validate_security_csv_row_column_count_matches_header),
    ("no_duplicate_security_csv_ids", _validate_no_duplicate_security_csv_ids),
    ("message_post_requires_mail_thread_inherit", _validate_message_post_requires_mail_thread_inherit),
    ("message_post_ensures_partner_is_follower", _validate_message_post_ensures_partner_is_follower),
    # `activity_calls_require_activity_mixin_inherit` deliberately removed from this internal-loop
    # list (2026-08-07, HUMAN_DECISION push, task046): unlike its sibling
    # `message_post_requires_mail_thread_inherit` above, this sync check's false-positive rate on
    # a real `_inherit`-only extension of an already-mixin-providing model (confirmed live,
    # project.meerwerk) was directly, repeatedly observed causing wasted internal-fix-loop retries
    # that triggered 3 consecutive real qwen3-coder-30b-a3b repetition-loop infra crashes on the
    # same task. The accurate, live-lookup-based sibling
    # (`_validate_activity_calls_require_activity_mixin_inherit_live`) already runs at the final
    # hard gate, so removing the sync check here only removes a proven-unreliable in-loop
    # fast-path, not the real correctness guarantee.
    ("model_declares_name_or_inherit", _validate_model_declares_name_or_inherit),
    ("name_attribute_matches_odoo_naming_convention", _validate_name_attribute_matches_odoo_naming_convention),
    ("model_class_is_not_a_pure_identity_stub", _validate_model_class_is_not_a_pure_identity_stub),
    # Real, confirmed gap found live (2026-08-09, task 07141af5's flagship run,
    # project_ticket_counts node): the sibling _inherit-only shape of the pure-identity-stub
    # check right above -- wired into the external hard gate (_validate_generated_module) but
    # NOT into this internal-loop subset, so the model never actually got a real, in-round
    # chance to patch it before the round failed outright. Confirmed live: 4 consecutive
    # resumes with an increasingly explicit, correctly CRITICAL-prioritized note all produced
    # the byte-identical empty class, because the internal loop's own faster self-correction
    # never saw this finding at all -- it only reached the model as a hard, round-ending
    # rejection, never as an actionable in-loop patch prompt.
    ("inherit_only_class_is_not_empty", _validate_inherit_only_class_is_not_empty),
    (
        "compute_field_depends_does_not_include_itself",
        _validate_compute_field_depends_does_not_include_itself,
    ),
    (
        "compute_field_depends_does_not_reference_other_models_own_fk_field",
        _validate_compute_field_depends_does_not_reference_other_models_own_fk_field,
    ),
    ("no_empty_ref_attribute", _validate_no_empty_ref_attribute),
    ("view_arch_has_single_root_element", _validate_view_arch_has_single_root_element),
    ("env_model_lookup_uses_dotted_model_name", _validate_env_model_lookup_uses_dotted_model_name),
    ("no_view_record_self_inherits", _validate_no_view_record_self_inherits),
]


def _run_internal_loop_narrow_validators(
    generated: "GeneratedModuleFiles",
    old_models_py: str = "",
    constraint_status: dict | None = None,
    goal: str = "",
) -> list[str]:
    """Runs the narrow ACI validator subset (§24.2.1) against `generated`, returning a plain-
    text finding per failing check. This is exposed to the MODEL's own reasoning (via the patch
    prompt below), not just a downstream deterministic gate -- the real distinction §24.1 point 1
    draws between "a check runs" (already true, ~247 functions in the full external chain) and "the
    model sees the result and acts on it" (the actual gap this section closes). Never a replacement
    for the full external `_validate_generated_module()` chain (§24.5) -- only a small, fast,
    high-signal preview of the mistake shapes that chain is most likely to reject anyway.

    `old_models_py`/`constraint_status` (2026-08-04): real, confirmed gap found live in the same-
    night full 30-task sweep (task029) -- `_validate_single_constraint_field_scope()` (the
    external-gate check that catches Build over-generating scope on a decomposed single-
    constraint round) already existed and DID correctly flag it, but only at the full external
    round-level gate; task029 burned its whole round budget re-submitting the same scope
    violation before finally escalating, because the internal loop's own faster self-correction
    never saw this finding. Both params optional and default to a no-op (empty string / None) so
    this stays additive -- a caller with no prior-round baseline (genuine round 1) or no
    decomposed constraint_status (a non-decomposed task) sees byte-identical behavior to before.

    `goal` (2026-08-07, HUMAN_DECISION escalation push, task025, real task_id
    31eed0c2-87e4-4216-9d48-bc94c3973bc3): real, confirmed gap -- every validator in
    `_INTERNAL_LOOP_NARROW_VALIDATORS` is a single-arg `Callable[[GeneratedModuleFiles], None]`,
    so `model_class_is_not_a_pure_identity_stub`'s own goal-gated views-only exemption (added for
    task007/task025's shared views-stripping fix) could never fire here even after being fixed at
    the external hard gate -- confirmed live: the exact same false-positive fired 4 times in one
    relaunch's own internal loop, contributing to a `task_cut_off` repetition-loop crash. Threaded
    through by name (not a full signature change to the shared list, to avoid touching every other
    single-arg validator) so this one check alone gets the same live-schema-independent, goal-only
    context its external sibling already has.
    """
    findings = []
    for label, fn in _INTERNAL_LOOP_NARROW_VALIDATORS:
        try:
            if label == "model_class_is_not_a_pure_identity_stub":
                fn(generated, goal)
            else:
                fn(generated)
        except ValueError as exc:
            findings.append(f"{label}: {exc}")
    if constraint_status:
        try:
            _validate_single_constraint_field_scope(generated, old_models_py, constraint_status)
        except ValueError as exc:
            findings.append(f"single_constraint_field_scope: {exc}")
    return findings


def _internal_loop_state_hash(generated: "GeneratedModuleFiles") -> str:
    """Hashes the exact file content a narrow-validator finding was computed against (§24.2.3's
    state-bound guardrail, arXiv:2607.24604's own measured 34/135-regressions-vs-4/135 result for
    stale vs. current-state-matched feedback). A `Patch` action must never be applied against
    content that has already drifted from what its own feedback describes.
    """
    files = _files_from_generated(generated)
    canonical = "\x00".join(f"{path}={files[path]}" for path in sorted(files))
    return hashlib.sha256(canonical.encode()).hexdigest()


def _internal_loop_budget_exceeded(steps_used: int, elapsed_sec: float) -> str | None:
    """Pre-call-checked dual budget (§24.2.2), the exact enforcement shape
    infra/cloud_escalation.py's decide_cloud_escalation() already uses for its own ceiling --
    checked BEFORE the next call is allowed to start, by the controller (run_build_internal_loop
    below), never left to Build's own judgment. Two independent caps, matching OpenHands'
    AgentController dual step+budget bound: step count, and real wall-clock duration (§24.2.2's
    "tracked independently of step count").
    """
    if steps_used >= MAX_INTERNAL_LOOP_STEPS:
        return f"step cap ({MAX_INTERNAL_LOOP_STEPS}) reached"
    if elapsed_sec >= MAX_INTERNAL_LOOP_DURATION_SEC:
        return f"duration cap ({MAX_INTERNAL_LOOP_DURATION_SEC:.0f}s) reached"
    return None


def flag_internal_loop_budget_exhaustion(steps_used: int, step_cap: int) -> dict | None:
    """Informational-only signal (§24.2.2's budget-exhaustion-as-signal, research technique #8) --
    same log-only contract as manager.learning.flag_llm_call_count_outlier() (never gates or
    pauses anything, side-effect-free): SWE-agent's own real data shows failing runs consume
    materially more of their step budget while flailing than successful runs do (median 12-of-30
    steps for success vs. mean 21-of-30 for failure) -- reaching the internal loop's own hard step
    cap without ever reaching a Keep is the same shape of signal, just at a much smaller scale.
    Returns None whenever the cap wasn't actually reached (a `Patch`-mechanics failure or a
    regression revert can also end the loop early, at fewer steps than the cap -- that's a
    different kind of "stuck," not budget exhaustion, and isn't flagged here).
    """
    if steps_used < step_cap:
        return None
    return {
        "steps_used": steps_used,
        "step_cap": step_cap,
        "message": (
            f"Build's internal check/revise loop used its full {step_cap}-step budget without "
            "reaching a Keep -- informational only, not a gate. Falling through to the existing "
            "external round path unchanged."
        ),
    }


@dataclass
class InternalLoopOutcome:
    """The typed result of run_build_internal_loop() -- `action` is always exactly "keep" (a
    narrow-validator-clean candidate was reached within budget) or "escalate" (§24.2.3's
    `Escalate`: internal loop exhausted or stuck -- fall through to the existing external round
    path unchanged, nothing new there). `generated` is always the last-known-good candidate seen
    (§24.2.3: a regression is reverted, never compounded forward)."""
    generated: "GeneratedModuleFiles"
    action: Literal["keep", "escalate"]
    steps_used: int
    findings_history: list[list[str]]
    budget_exhausted: bool


def _candidate_execution_fingerprint(generated: "GeneratedModuleFiles") -> tuple:
    """Phase 30 §26 item 12: a lightweight, deterministic proxy for "would these candidates
    behave the same" -- the full execution-grounded voting research this item cites (Semantic
    Voting, arXiv:2605.08680/2604.15618) clusters SAMPLED candidates by actual install/test-
    EXECUTION outcome; adding a real sandbox install to every best-of-N candidate (best-of-N
    currently does zero execution, only pre-write static validation) would be a materially
    larger, separate per-round cost/infra change than this item's own stated scope ("extends,
    not replaces, the existing... scoring"), and is deliberately not added here without being
    asked to expand per-round spend. This is the cheapest real, deterministic, already-available
    signal that approximates it: the STRUCTURAL shape of what a candidate actually defines
    (model identity + field names + method names, via ast.parse, never executed) -- two
    candidates with genuinely different wording/formatting but the identical real shape cluster
    together, the way naive text/regression-count-only comparison (this function's own prior
    sole signal) cannot distinguish "truly redundant" from "coincidentally same regression
    count." Unparseable content (a syntax error) never collapses with anything else -- returns
    the raw text itself as a guaranteed-unique fingerprint, so a broken candidate can never be
    mistaken for consensus with a working one.
    """
    try:
        tree = ast.parse(generated.models_py)
    except SyntaxError:
        return (generated.models_py,)

    model_names: set[str] = set()
    field_names: set[str] = set()
    method_names: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        for stmt in node.body:
            if isinstance(stmt, ast.Assign):
                for target in stmt.targets:
                    if not isinstance(target, ast.Name):
                        continue
                    if target.id in ("_name", "_inherit") and isinstance(stmt.value, ast.Constant):
                        model_names.add(str(stmt.value.value))
                    elif not target.id.startswith("_"):
                        field_names.add(target.id)
            elif isinstance(stmt, ast.FunctionDef):
                method_names.add(stmt.name)
    return (frozenset(model_names), frozenset(field_names), frozenset(method_names))


class BuildSpecialist:
    """One instance per running process is fine -- all real state
    (locks, fence tokens) lives in Redis, not on this object, so two
    concurrent BuildSpecialist instances (even in the same process, in
    different tasks) correctly contend for the same lock -- true again
    as of Phase 26B (2026-07-27): before that fix, `_run_module_dev()`
    keyed its own acquire/check_fence/release calls on `module_name`,
    this task's own scaffold directory name (always unique per
    task_id by construction, via `slugify_module_name()`'s own hash
    suffix), so two DIFFERENT tasks editing the exact same real Odoo
    model could never actually contend for anything. Now keyed on
    `contract.module_identity` (the real model being touched) when
    resolved, falling back to `module_name` only when it isn't.
    """

    def __init__(self, client: ModelGatewayClient, db: str, model: str | None = None):
        self.client = client
        self.db = db
        self.model = model or os.environ.get(_DEFAULT_MODEL_ENV, _DEFAULT_MODEL_FALLBACK)

    async def run(self, contract: TaskContract) -> SpecialistOutput:
        if contract.capability_class == CapabilityClass.module_development:
            return await self._run_module_dev(contract)
        if contract.capability_class == CapabilityClass.data_change:
            return await self._run_data_change(contract)
        return SpecialistOutput(
            task_id=contract.task_id,
            specialist_type=contract.specialist_type,
            summary=(
                f"BuildSpecialist does not handle capability_class={contract.capability_class!r} "
                f"-- readonly_investigation is Code-Review's job (Phase 10), not Build's."
            ),
            detail={},
            claims_complete=False,
        )

    async def _run_module_dev(self, contract: TaskContract) -> SpecialistOutput:
        task_id_str = str(contract.task_id)
        edit_existing_module = _extract_edit_existing_module(contract)
        module_name = edit_existing_module or slugify_module_name(contract.goal, task_id_str)
        # Phase 26B follow-up (2026-07-27, audit Finding #2): real,
        # deeper bug found while live-verifying the module-identity fix
        # -- `acquire_module_lock()`/`check_fence()`/`release_module_
        # lock()` below were ALWAYS keyed on `module_name`, this task's
        # own scaffold directory name, which `slugify_module_name()`
        # makes unique per task_id BY CONSTRUCTION (a `hashlib.sha256
        # (task_id...)[:8]` suffix on every call) -- so two DIFFERENT
        # tasks editing the exact same real Odoo model could never
        # collide on this lock, no matter what `contract.module_identity`
        # resolves to. Fixing `module_lock_name`'s own VALUE at the
        # manager/loop.py level (the fix directly above/upstream) was
        # necessary but not sufficient: this file's own lock/fence calls
        # never actually read that value at all. The RESOURCE this lock
        # is meant to protect is the real Odoo model being written to,
        # not this task's own always-unique scaffold directory -- so
        # `lock_key` (used for every acquire/check_fence/release call
        # below, module_name itself is untouched, still used for the
        # scaffold directory/manifest/install target) is the real model
        # identity when known, falling back to `module_name` (today's
        # prior behavior, never worse) when it isn't.
        lock_key = contract.module_identity or module_name
        completed_steps: list[CompensatingAction] = []

        depends_on_modules = _extract_depends_on_modules(contract)
        depends_on_module = depends_on_modules[0] if depends_on_modules else None
        try:
            _validate_module_name_not_reused(module_name, depends_on_modules)
        except ValueError as exc:
            return SpecialistOutput(
                task_id=contract.task_id,
                specialist_type=contract.specialist_type,
                summary=str(exc),
                detail={"module_name": module_name},
                claims_complete=False,
            )

        target_module_files: dict[str, str] = {}
        if depends_on_module:
            try:
                # Real, confirmed bug found live (2026-07-24, 50-task
                # sequential re-run, task 001): read_module_files() dumps
                # the ENTIRE target module -- fine for a small, freshly-
                # scaffolded oma_* module (its other real use case), but
                # a genuinely large real SITE module (mis_base_extend:
                # 135 files, 27,031 lines) blew straight through the
                # backend's own 98,304-token context ceiling on the very
                # first generation call, for a task that only needed ONE
                # model's own file. read_module_files_relevant_to_goal()
                # greps for just the file(s) the task's own goal text
                # actually concerns (same discipline as this file's own
                # find_module_defining_model()), under a hard total-size
                # cap regardless.
                target_module_files = read_module_files_relevant_to_goal(depends_on_module, contract.goal)
            except CodebaseReadError as exc:
                return SpecialistOutput(
                    task_id=contract.task_id,
                    specialist_type=contract.specialist_type,
                    summary=(
                        f"depends_on_module={depends_on_module!r} was supplied, but its real "
                        f"source could not be read: {exc}"
                    ),
                    detail={"module_name": module_name},
                    claims_complete=False,
                )

        # Phase 31 §6/Phase B (2026-08-08): real bug found live during the Phase B controlled
        # concurrency experiment -- the plain acquire_module_lock() has no concept of "the
        # current holder is my own sibling node, not a different task," so two concurrent nodes
        # of the SAME decomposed task racing on the same module would have the second one
        # hard-rejected outright. acquire_module_lock_same_task_aware() waits (bounded, async)
        # for a same-task sibling to release before re-attempting; a genuinely different task's
        # collision is still rejected immediately, exactly as before -- see its own docstring.
        lock = await acquire_module_lock_same_task_aware(lock_key, task_id_str)
        if not lock.acquired:
            # Phase 26B follow-up (2026-07-27): real, live-reproduced bug
            # found the moment this rejection path became genuinely
            # reachable for the first time (previously, module_name's own
            # per-task-unique hash suffix meant two tasks could never
            # actually collide here at all). manager/loop.py's own
            # `should_run_code_review`/`verification_will_be_skipped`
            # checks only ever excluded a SANDBOX failure
            # (`detail.get("sandbox_failed")`) from triggering Code-
            # Review's diff step -- but a lock rejection happens even
            # EARLIER than that, before any scaffold/write call at all,
            # so `"module_name" in detail` was still true and Code-Review
            # got invoked to diff a module directory that was NEVER
            # actually written, producing a confusing, misleading "no
            # files found under ..." finding instead of the real, simple
            # "another task is currently editing this model" reason.
            # `lock_rejected: True` lets loop.py's own checks correctly
            # exclude this case the same way sandbox_failed already is.
            return SpecialistOutput(
                task_id=contract.task_id,
                specialist_type=contract.specialist_type,
                summary=f"Model {lock_key!r} is currently locked by another task -- refusing to proceed concurrently.",
                detail={"module_name": module_name, "lock_rejected": True},
                claims_complete=False,
            )

        try:
            try:
                constitution_text = load_odoo_development_constitution()
            except ConstitutionNotFoundError as exc:
                return SpecialistOutput(
                    task_id=contract.task_id,
                    specialist_type=contract.specialist_type,
                    summary=str(exc),
                    detail={"module_name": module_name},
                    claims_complete=False,
                )

            skill_text = _MODULE_SCAFFOLDING_SKILL_PATH.read_text()

            try:
                publish_trace_event(task_id_str, {
                    "level": "specialist", "actor": "bug_fix", "message": f"Scaffolding module {module_name}…", "status": "running",
                })
                is_retry = False
                try:
                    await asyncio.to_thread(scaffold_module, module_name)
                    completed_steps.append(
                        CompensatingAction(
                            forward_step=f"scaffold module {module_name}",
                            undo_action=f"remove_scaffolded_module:{module_name}",
                        )
                    )
                except ScaffoldError:
                    # A real, organic gap found during a real (not
                    # synthetic) Phase 15 verification pass: module
                    # names are derived deterministically from the
                    # goal text (slugify_module_name), which stays
                    # IDENTICAL across a round loop's retries -- so a
                    # task's own round 2 always collides with its own
                    # round 1 scaffold, which never gets cleaned up
                    # (round 1 didn't crash; it built, installed, and
                    # then failed verification, a normal, non-exception
                    # outcome). Previously this propagated as a bare,
                    # uncaught ScaffoldError -- a raw 500, bypassing the
                    # entire round loop. Fixed: reuse the existing
                    # scaffold on a genuine retry of the SAME module
                    # rather than refusing -- the whole point of a
                    # retry is to overwrite the prior attempt's
                    # generated files with a revised one, not to start
                    # over from a fresh skeleton every round.
                    is_retry = True

                # Root cause found live (2026-07-12) after 48 rounds of a
                # single task never passing once: `odoo-bin scaffold`
                # (above) always creates its own full stock module tree
                # (controllers/, demo/, views/templates.xml) that
                # GeneratedModuleFiles has no field for and Build can
                # never legitimately populate -- Code-Review was
                # correctly rejecting THIS leftover scaffold boilerplate
                # every round, not anything the LLM generated. Stripped
                # here, deterministically, before anything reads the
                # module directory (old_files_by_relpath below, Build's
                # own LLM call, Code-Review) ever sees it -- idempotent,
                # so it's safe to run on a genuine retry too (is_retry
                # branch above), in case an earlier round of this same
                # task predates this fix.
                stripped = await asyncio.to_thread(strip_scaffold_boilerplate, module_name)
                if stripped:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix",
                        "message": f"Stripped {len(stripped)} unused scaffold file(s): {stripped}",
                        "status": "running",
                    })

                # Phase 16 (diff rendering): a real "old" snapshot for
                # the diff, taken BEFORE this round's own writes land --
                # empty for a brand-new module (round 1, nothing
                # meaningful existed yet -- odoo-bin scaffold's own
                # placeholder boilerplate is deliberately not treated as
                # "old" content, it's noise, not something this task
                # actually wrote), or this module's own real prior
                # content for a genuine same-task retry.
                #
                # Phase 18 (§22.6): the diff base -- and the source
                # _generate_code() actually reasons from for a retry --
                # now comes from the task's own last VALIDATED Gitea
                # commit (vcs.read_last_validated_commit()), not a live
                # SSH read of the container's filesystem. This
                # structurally eliminates the race condition a live read
                # has against a concurrently-writing round (§22.4,
                # problem #1). `prior_committed_files` (Gitea-sourced,
                # module-namespace-stripped) is what's offered to
                # _generate_code() for scoped-edit mode; the live SSH
                # read is kept ONLY as a fallback for the rare case
                # nothing has been committed yet for a genuine retry
                # (e.g. Gitea was unavailable on round 1) -- never as the
                # scoped-edit source itself, since an ungoverned live
                # read is exactly what this component exists to retire
                # for that purpose.
                old_files_by_relpath: dict[str, str] = {}
                prior_committed_files: dict[str, str] | None = None
                if is_retry and contract.frozen_old_files_by_relpath is not None:
                    # Phase 31 §6(a): a per-node dispatch's own FROZEN snapshot -- taken once, at
                    # dispatch time, by manager/graph_scheduler.py's own caller -- takes priority
                    # over this branch's own live Gitea read whenever the contract carries one.
                    # None (the default, every existing call site unaffected) preserves this
                    # branch's exact prior behavior byte-for-byte below. Skipping the live read
                    # here is deliberate: a node's own generation context must stay pinned to
                    # what it saw at dispatch, never silently pick up a LATER node's own
                    # concurrent commit mid-generation.
                    module_prefix = f"{module_name}/"
                    old_files_by_relpath = {
                        path.removeprefix(module_prefix): content
                        for path, content in contract.frozen_old_files_by_relpath.items()
                        if path.startswith(module_prefix)
                    }
                    prior_committed_files = old_files_by_relpath
                elif is_retry:
                    try:
                        commit_content = vcs.read_last_validated_commit(task_id_str)
                    except vcs.VcsError as exc:
                        commit_content = None
                        publish_trace_event(task_id_str, {
                            "level": "specialist", "actor": "bug_fix",
                            "message": f"Gitea baseline read failed, falling back to live read: {exc}",
                            "status": "running",
                        })
                    if commit_content:
                        module_prefix = f"{module_name}/"
                        prior_committed_files = {
                            path.removeprefix(module_prefix): content
                            for path, content in commit_content.items()
                            if path.startswith(module_prefix)
                        }
                        old_files_by_relpath = prior_committed_files
                    else:
                        prefix = f"/mnt/extra-addons/{module_name}/"
                        for abs_path, content in read_module_files(module_name).items():
                            old_files_by_relpath[abs_path.removeprefix(prefix)] = content
                        # Real bug found live (2026-07-13): this live-SSH-read
                        # fallback only ever populated old_files_by_relpath,
                        # which the deterministic post-write validators
                        # (_validate_view_fields_exist_on_model,
                        # _validate_single_constraint_field_scope) diff
                        # against -- but _generate_code() below only enters
                        # its scoped-edit path `if prior_files:`, and
                        # prior_committed_files stayed None here, so it fell
                        # through to full-regeneration mode instead, ignoring
                        # the real live file entirely. This is exactly the
                        # shape a genuine follow-up task hits: a brand-new
                        # task_id (so is_retry is only True because the
                        # deterministic module_name -- derived from the goal
                        # text explicitly naming an existing module -- already
                        # exists on disk) with no Gitea commit history of its
                        # OWN (so commit_content is None), even though the
                        # module itself has substantial real content from a
                        # DIFFERENT prior task. Confirmed live: Build
                        # regenerated the whole model from scratch, the
                        # deterministic scope validator correctly rejected 13
                        # "new" fields that were actually already-existing
                        # ones, and a sibling round's view correctly
                        # referenced real existing fields but got rejected by
                        # _validate_view_fields_exist_on_model because
                        # generated.models_py (freshly regenerated, not
                        # scoped-edited) never carried them forward. Fixed by
                        # also feeding this live-read baseline into
                        # prior_committed_files, so the live-fallback path
                        # gets the same scoped-edit generation mode as the
                        # Gitea-committed path, not just the same validation.
                        prior_committed_files = dict(old_files_by_relpath)

                        # Real, severe, general root cause found live
                        # (2026-07-15, chasing what looked like a stubborn
                        # "views_xml has value/value2" mistake that survived
                        # every prompt fix): this live-read fallback is only
                        # SUPPOSED to fire for two legitimate cases (see the
                        # comment above) -- but there is a THIRD, much more
                        # common case it silently mishandles: round 1 fails
                        # pre-write validation for EVERY best-of-N candidate
                        # (nothing is ever written to the real container, no
                        # Gitea commit ever happens), so on round 2 this
                        # fallback reads whatever odoo-bin scaffold's own
                        # UNMODIFIED stock demo tutorial model still sits in
                        # models/models.py -- strip_scaffold_boilerplate()
                        # only ever removes EXTRA files, it never touches
                        # this file's own content. That raw scaffold
                        # (Odoo's own well-known "value"/"value2" compute
                        # example) then gets handed to the scoped-edit
                        # prompt as if it were "the current, VALIDATED, real
                        # content" -- confirmed live: the LLM dutifully
                        # edited Odoo's own tutorial demo, producing exactly
                        # the value/value2-contaminated views_xml (and, one
                        # round later, an "add_field target not found"
                        # failure against that same demo class) that looked
                        # like a model reliability problem but was this
                        # module never having had any real content to edit
                        # in the first place. odoo-bin scaffold's own stock
                        # model is always self-referentially named
                        # `_name = '<module>.<module>'` -- a pattern no real
                        # generated content would ever produce -- so it's a
                        # reliable, structural (not per-task) signature for
                        # "this is untouched scaffold, not real prior
                        # content." Detected, this round correctly falls
                        # through to full regeneration instead of a
                        # scoped edit against a baseline that was never real.
                        _scaffold_signature = f"_name = '{module_name}.{module_name}'"
                        if _scaffold_signature in old_files_by_relpath.get("models/models.py", ""):
                            old_files_by_relpath = {}
                            prior_committed_files = None
                            publish_trace_event(task_id_str, {
                                "level": "specialist", "actor": "bug_fix",
                                "message": (
                                    "Live-read fallback found only odoo-bin scaffold's own untouched "
                                    "demo content (no real prior round ever wrote to this module) -- "
                                    "forcing full regeneration instead of a scoped edit against it."
                                ),
                                "status": "running",
                            })

                # Real, confirmed follow-up gap found live (2026-08-09, task 07141af5's flagship
                # run, project_ticket_counts node): _validate_inherit_only_class_is_not_empty()
                # (and its sibling _validate_model_class_is_not_a_pure_identity_stub()) only ever
                # check the round's OWN new candidate output -- neither has any way to catch this
                # exact defect already sitting in the git-committed BASELINE (old_files_by_relpath),
                # e.g. from an earlier round that committed it before this validator existed.
                # Confirmed live: once that happens, every subsequent scoped-edit round sees an
                # already-existing class with the right `_inherit` line in its own "CURRENT
                # CONTENT" prompt context and reasonably, but wrongly, treats it as already
                # handled -- scoped-edit generation only ever touches what it's explicitly told
                # to, so the broken content just gets carried forward unchanged, forever,
                # independent of temperature, notes, or candidate count (confirmed live: 8+
                # consecutive resumes, several with genuine multi-candidate diversity after
                # raising candidate_count, all produced byte-for-byte identical output). Checking
                # the baseline HERE, once per round, and surfacing any defect found as an explicit
                # CRITICAL_RULE_PREFIX rule breaks that cycle -- the model is now told point-blank
                # that EXISTING content (not just its own new output) needs fixing this round.
                if old_files_by_relpath:
                    _baseline_defect = _find_empty_inherit_class_defect(
                        old_files_by_relpath.get("models/models.py", "")
                    )
                    if _baseline_defect:
                        contract = contract.model_copy(update={
                            "rules": [
                                *contract.rules,
                                f"{CRITICAL_RULE_PREFIX}The EXISTING, already-committed models.py "
                                f"has a real, confirmed defect that a prior round left broken -- "
                                f"you must fix it as part of this round's own work, not just add "
                                f"new content elsewhere and leave it as-is: {_baseline_defect}",
                            ],
                        })

                # Real, confirmed, severe bug found live (Phase 18 dynamic
                # verification pass, task 2, round 5): none of these
                # deterministic pre-write validators were ever wrapped in
                # a try/except here, unlike _validate_module_name_not_reused
                # above -- a real ValueError from any of them propagated
                # all the way out of delegate_to_specialist(), out of
                # run_turn(), and crashed the entire HTTP request with a
                # raw 500 (confirmed directly in the server's own log).
                # completed_steps is still empty at this point (install
                # hasn't run yet), so the outer `except Exception` below
                # doesn't even wrap it as a PartialTaskFailure -- it just
                # re-raises bare. The task was left stuck forever: Redis
                # state still said "running," no round got recorded, no
                # escalation fired, nothing -- silent task death, not a
                # slow round. Fixed generally: any of these four checks
                # failing (now including _generate_code() itself, whose
                # Phase 18 scoped-edit path (§22.6) can raise ValueError
                # from _apply_scoped_edits()) is exactly the same kind of
                # "this generation attempt was bad, fail the round and
                # let the loop retry" outcome as every other failure path
                # already handles gracefully -- caught here now, same
                # pattern as the module-name-reuse check above.
                generated: GeneratedModuleFiles | None = None
                candidate_count_used = 1
                try:
                    # Routes 2+-constraint rounds, and (Phase 25D)
                    # single-constraint rounds whose goal_facts confirms
                    # open-ended logic, through multi-candidate best-of-N
                    # generation -- see _should_use_best_of_n()'s own
                    # docstring for the full reasoning and history.
                    if _should_use_best_of_n(contract):
                        generated, candidate_count_used = await self._generate_best_of_n(
                            contract, constitution_text, skill_text, module_name,
                            depends_on_module, target_module_files, prior_committed_files,
                            old_files_by_relpath,
                        )
                    else:
                        # Phase T (§24.2.2): _generate_code() itself now applies the internal
                        # check/revise loop internally (round 2 of the coverage extension,
                        # 2026-08-04 -- see _generate_code()'s own docstring), covering this
                        # single-candidate path, the scoped-edit retry path, AND the fallback-
                        # rewrite path from one single wrap point, never a second, separate
                        # implementation here.
                        #
                        # Real, confirmed structural gap found live (2026-08-09, task 07141af5's
                        # flagship run, project_ticket_counts node): this call has always been
                        # temperature=0.0 (the parameter default), completely independent of
                        # `contract.resumed_from_checkpoint_count` -- so a genuinely fresh resume
                        # (a brand new top-level call, not a within-call repetition retry) starts
                        # from the exact same deterministic sampling as the very first attempt
                        # every single time. Confirmed live: 5+ consecutive resumes of the same
                        # node, each with a different, increasingly explicit, correctly
                        # CRITICAL_RULE_PREFIX-prioritized note, produced byte-for-byte IDENTICAL
                        # generated content -- exactly what temperature=0.0 deterministic
                        # sampling guarantees whenever the prompt's own most decision-relevant
                        # tokens don't shift the model's greedy decoding path, regardless of how
                        # many times it's retried. This codebase already has a proven, working
                        # precedent for exactly this diversity problem -- `_generate_best_of_n()`
                        # right above uses `temperature=0.0 if i == 0 else 0.4` for its own
                        # candidates -- reusing that SAME established, non-zero diversity value
                        # here once a node has genuinely been resumed at least once, rather than
                        # inventing a new one.
                        effective_temperature = 0.4 if contract.resumed_from_checkpoint_count > 0 else 0.0
                        generated = await self._generate_code(
                            contract, constitution_text, skill_text, module_name,
                            depends_on_module, target_module_files,
                            prior_files=prior_committed_files,
                            temperature=effective_temperature,
                        )
                        await _maybe_override_view_xml_deterministically(
                            generated, self.db, task_id_str, goal=contract.goal, module_name=module_name,
                        )
                        _maybe_override_security_csv_deterministically(
                            generated, contract.goal, module_name, task_id_str,
                        )
                        await self._validate_generated_module(
                            generated, module_name, depends_on_module,
                            old_models_py=old_files_by_relpath.get("models/models.py", ""),
                            old_views_xml=old_files_by_relpath.get("views/views.xml", ""),
                            old_security_xml=old_files_by_relpath.get("security/security.xml", ""),
                            old_manifest_py=old_files_by_relpath.get("__manifest__.py", ""),
                            old_files_by_relpath=old_files_by_relpath,
                            constraint_status=contract.constraint_status,
                            goal=contract.goal,
                            original_goal=contract.original_goal,
                            goal_facts=contract.goal_facts,
                            task_id=task_id_str,
                            remaining_constraint_labels=contract.remaining_constraint_labels,
                        )
                except (ValueError, StructuredOutputError) as exc:
                    # StructuredOutputError added 2026-07-23 (Phase 21
                    # fix-pass): a call_structured() retry that never
                    # converges (e.g. the model repeatedly omits a
                    # schema field across all 3 re-ask attempts) is a
                    # RuntimeError subclass, NOT a ValueError -- it was
                    # propagating straight past this handler and
                    # crashing the whole task instead of failing just
                    # this one round (confirmed: 15 of 49 non-passing
                    # tasks in the 2026-07-22 SITE 50-task benchmark
                    # crashed this way). Treated the same as any other
                    # round-generation failure here: report it and let
                    # the manager's own round-retry loop decide whether
                    # to try again, same as a ValueError always has.
                    #
                    # Real, confirmed bug found live (Phase 18 dynamic
                    # verification pass, task 2 resumed rounds): including
                    # "module_name" here made manager.loop.py's own
                    # Code-Review gate (`"module_name" in build_output.
                    # detail`) fire even though NOTHING new was actually
                    # written this round (write_module_file() never runs
                    # -- these validators reject BEFORE any write).
                    # Code-Review then reviewed whatever was already on
                    # disk -- on a round where every prior attempt also
                    # got rejected pre-write, that's still odoo-bin
                    # scaffold's own placeholder boilerplate (genuinely
                    # commented-out example code) -- producing a real but
                    # deeply misleading "entire model class is commented
                    # out" finding that had nothing to do with what this
                    # round's LLM actually generated or got rejected for.
                    # Confirmed live: the exact same finding, including
                    # the exact same stale model-id string, recurred
                    # across many rounds while Build was actually being
                    # rejected for a completely different, already-fixed
                    # reason each time. Fixed generally: omit module_name
                    # here so Code-Review correctly skips a round with no
                    # fresh diff to review, and the real validator
                    # rejection message (this round's own actual, current
                    # problem) is what reaches the next round's rules
                    # instead of a stale, unrelated Code-Review complaint.
                    return SpecialistOutput(
                        task_id=contract.task_id,
                        specialist_type=contract.specialist_type,
                        summary=str(exc),
                        # _generate_code() itself (the scoped-edit apply
                        # step, §22.6) can now be the thing that raised
                        # this ValueError, before `generated` was ever
                        # assigned -- guard rather than assume it exists.
                        #
                        # "sandbox_failed": True added here too (2026-08-12 overnight Phase 35
                        # Context-row bake-in, ctx03_many2one, real task_id
                        # 7f495af8-d7b8-49d5-8aa2-575c1f50b7f1) -- this catch already correctly
                        # omits "module_name" (see the comment above) so Code-Review can't review a
                        # stale, unrelated disk state, but manager/loop.py's OWN verification
                        # short-circuit (should_run_code_review/verification_will_be_skipped) keys
                        # specifically on the "sandbox_failed" flag, not on "module_name" being
                        # absent -- without it, a pre-write validator rejection (e.g. the
                        # self-inherit check) fell through to the real await_verification() path,
                        # which tries to verify against something that was never actually written
                        # this round, so the next round's correction notes came back generic/
                        # misleading instead of this round's own specific, real finding text.
                        # Confirmed live: the exact same self-inherit rejection reproduced
                        # byte-for-byte across 2 consecutive rounds before this fix. Reuses the
                        # exact same flag name and short-circuit path already proven for the
                        # sandbox-failure and lock-rejection siblings -- not a new mechanism.
                        detail={
                            "self_report_uncertain": generated.notes if generated else None,
                            "sandbox_failed": True,
                        },
                        claims_complete=False,
                    )
                # Real, confirmed bug found live (2026-08-09, task
                # 07141af5-9a4e-41b6-93ea-8b7af04fea9c's flagship run, service_ticket_model
                # node): the sibling calls to this same autofix further down this function
                # (right after the pre-write validator/autofix chain begins, and again after
                # the model-name-to-inherit rewrite) both run AFTER `new_files_by_relpath` is
                # captured here -- `_files_from_generated(generated)` snapshots
                # `generated.models_py`'s CURRENT string value into a plain dict; Python strings
                # are immutable, so a LATER `generated.models_py = ...` reassignment never
                # propagates back into that already-captured dict, meaning every downstream
                # consumer (sandbox pre-flight, the real diff, apply_node_result_to_module's own
                # commit) kept seeing the UN-deduped content regardless of what those later
                # autofix calls did to `generated` itself. Confirmed live via direct Gitea
                # inspection: the real committed models.py still had the duplicate line even
                # after this same autofix supposedly ran. Running it here, immediately before
                # this snapshot is taken, is the one placement guaranteed to actually reach the
                # round's real output.
                _autofix_dedupe_consecutive_identical_lines(generated)
                # Real, confirmed bug found live (2026-08-10, task e65381cc, equipment_views_menu
                # node): the exact same snapshot-ordering bug this comment block already
                # documents for _autofix_dedupe_consecutive_identical_lines also affected
                # _autofix_manifest_missing_dependency_for_csv_model_refs's own later call
                # (further down this function, well after this snapshot) -- its CSV-qualifying
                # rewrite (`model_oma_equipment` -> `oma_build_a_complete_field_ab52b7f8.
                # model_oma_equipment`) never reached `new_files_by_relpath`, so sandbox
                # pre-flight kept installing the UN-qualified CSV and failing with "No matching
                # record found for external id 'model_oma_equipment'" every single round, even
                # after Bug 42's fix (this same file, resolve_owning_modules_fast's own
                # depends_on_module exemption) made the resolution itself work correctly --
                # sandbox pre-flight's own hard failure short-circuits the round before the
                # LATER, post-snapshot call (and the real self.db install after it) is ever
                # reached, so that later call's correct fix could never actually help. Running it
                # here too, immediately before the snapshot, the same placement already proven
                # correct for the dedupe sibling -- the later call further down remains as a
                # harmless, idempotent no-op safety net for any content changed after this point.
                await _autofix_manifest_missing_dependency_for_csv_model_refs(
                    generated, self.db, module_name, task_id=task_id_str, depends_on_module=depends_on_module,
                )
                new_files_by_relpath = _files_from_generated(generated)

                # Phase 18 (§22.4): commit this round's output to the
                # task's own Gitea branch -- the durable baseline the
                # NEXT round's own prior_files (§22.6) reads from --
                # immediately after pre-write validation passes and
                # BEFORE write_module_file() writes onto the live
                # container, per the plan's own ordering. A Gitea outage
                # here does not fail the round (the container write path
                # below is unconditional, unchanged from every phase
                # before this one) -- it just means commit_sha stays
                # None and the NEXT round's own retry falls back to the
                # live SSH read, exactly like today, one round later
                # than ideal, never a hard failure of this round.
                # Phase 31 §6(a): a per-node dispatch (contract.frozen_old_files_by_relpath is
                # not None -- set once, at dispatch time, by manager/loop.py's own
                # _run_constraint_labels_from()) commits to a PER-NODE branch and applies via
                # apply_node_result_to_module() below, instead of committing straight to the
                # task branch and writing the container directly. None (every non-decomposed
                # task, and every decomposed task's own legacy/fallback-linear-chain path)
                # preserves today's exact commit-to-task-branch behavior, byte-for-byte.
                node_label = contract.current_constraint_label if contract.frozen_old_files_by_relpath is not None else None

                commit_sha: str | None = None
                try:
                    round_number_for_commit = vcs.commit_count_for_task(task_id_str, node_label=node_label) + 1
                    commit_sha = vcs.commit_validated_round(
                        task_id=task_id_str,
                        module_name=module_name,
                        files=new_files_by_relpath,
                        round_number=round_number_for_commit,
                        summary=(generated.notes or "module update")[:200],
                        node_label=node_label,
                    )
                except vcs.VcsError as exc:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix",
                        "message": f"Gitea commit failed (continuing -- container write is unaffected): {exc}",
                        "status": "running",
                    })

                # Phase 20 (§24.13): prove this round's exact generated
                # files install cleanly in the isolated sandbox BEFORE
                # any of it ever touches the real, shared odoo16-dev.
                # A sandbox failure returns this round as a normal
                # failure (same shape as any other pre-write validator
                # rejection) -- Manager's existing next-round retry,
                # fed this failure's real message, is the "repair" half
                # of the loop; no real write happens below until this
                # passes.
                # Real, confirmed follow-on bug found live (2026-08-02, immediately after
                # shipping the ALREADY_SATISFIED_BY_COLLISION_MARKER fix above and re-testing it
                # live): the collision fix correctly recognizes the requested field already
                # exists for real on the REAL target (self.db), but views_xml -- built earlier,
                # before the collision autofix ran -- still references that exact field name.
                # The real target install would be fine (the field genuinely IS there), but the
                # sandbox pre-flight's own disposable, freshly-created database was NEVER touched
                # by whichever earlier task run actually created that field for real, so its own
                # copy of the target model doesn't have it -- a real, deterministic
                # `ParseError: Field "X" does not exist in model "Y"` on the SANDBOX specifically,
                # confirmed via the exact same live re-test that proved the collision fix itself
                # works. Structurally identical to the existing same-task-`_inherit` sandbox skip
                # immediately below (disposable sandbox has no memory of real target state that
                # genuinely exists elsewhere) -- same fix shape, same safety reasoning: Testing/QA
                # still independently re-verifies against the real target afterward regardless.
                already_satisfied_by_collision = (
                    _ALREADY_SATISFIED_BY_COLLISION_MARKER in (generated.notes or "")
                )
                skip_sandbox = already_satisfied_by_collision or await _sandbox_preflight_inapplicable_for_same_task_inherit(
                    generated, module_name, self.db, task_id=task_id_str,
                )
                if already_satisfied_by_collision:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix",
                        "message": (
                            "Sandbox pre-flight skipped: every field this round declared already "
                            "exists for real on the actual target -- the disposable sandbox has "
                            "no memory of that real state, so pre-flighting here would always "
                            "produce a false failure on a view referencing a field the real "
                            "target genuinely has. Verifying directly against the real target "
                            "instead, same as Testing/QA already does independently afterward."
                        ),
                        "status": "running",
                    })
                    sandbox_result = SandboxPreflightResult(
                        success=True, message="Sandbox pre-flight skipped (already satisfied by real-target collision).",
                    )
                elif skip_sandbox:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix",
                        "message": (
                            "Sandbox pre-flight skipped: this round extends a model this SAME "
                            "task's own earlier constraint already created for real -- the "
                            "disposable sandbox has no memory of that, so pre-flighting here "
                            "would always produce a false failure. Verifying directly against "
                            "the real target instead, same as Testing/QA already does "
                            "independently afterward."
                        ),
                        "status": "running",
                    })
                    sandbox_result = SandboxPreflightResult(
                        success=True, message="Sandbox pre-flight skipped (same-task _inherit target).",
                    )
                else:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix",
                        "message": "Sandbox pre-flight: testing this round's changes in isolation…",
                        "status": "running",
                    })
                    sandbox_result = await _sandbox_preflight(module_name, new_files_by_relpath, task_id_str)
                if not sandbox_result.success:
                    return SpecialistOutput(
                        task_id=contract.task_id,
                        specialist_type=contract.specialist_type,
                        summary=sandbox_result.message,
                        detail={
                            "module_name": module_name,
                            "sandbox_failed": True,
                            "sandbox_log_tail": sandbox_result.log_tail,
                            "self_report_uncertain": generated.notes,
                            "diff": _compute_module_diff(old_files_by_relpath, new_files_by_relpath),
                            "commit_sha": commit_sha,
                        },
                        claims_complete=False,
                    )

                def _fenced_write_module_file(relpath: str, content: str) -> None:
                    # Phase 31 §6(b): real gap found (2026-08-07) directly against this module's
                    # own docstring claim ("check_fence() is called immediately before every real
                    # Odoo write ... not optional") -- confirmed FALSE against the real body: the
                    # only check_fence() call in this whole method was the single one right
                    # before install, below, never before any of these individual writes. The
                    # lock's own 30s TTL can lapse mid-batch, letting a second acquirer's writes
                    # interleave with the first's remaining unguarded writes -- check_fence() is
                    # one cheap Redis EVAL and safe to call repeatedly with the same token (a
                    # no-op until a genuinely newer contender's token supersedes it), so re-
                    # checking before EVERY write closes that window at negligible cost.
                    if not check_fence(lock_key, lock.fence_token):
                        raise StaleForwardStepError(
                            f"fence check failed for {lock_key!r} before writing {relpath!r} -- "
                            f"another task has since taken over this model's lock; refusing to write."
                        )
                    write_module_file(module_name, relpath, content)

                def _fenced_delete_module_file(relpath: str) -> None:
                    """Real, confirmed bug found live (2026-08-11, task 18fca388): see
                    delete_module_file()'s own docstring -- writing was always conditional
                    ("if generated.views_xml: ..."), but nothing ever explicitly deleted the
                    file when that field went back to falsy, so a file genuinely written by an
                    EARLIER round survived on disk untouched forever, no matter what any LATER
                    round's own `generated` object said. Same fencing discipline as every write.
                    """
                    if not check_fence(lock_key, lock.fence_token):
                        raise StaleForwardStepError(
                            f"fence check failed for {lock_key!r} before deleting {relpath!r} -- "
                            f"another task has since taken over this model's lock; refusing to delete."
                        )
                    delete_module_file(module_name, relpath)

                if node_label is not None:
                    # Phase 31 §6(b)/(c)/(d): the real, serialized-apply step -- diffs this
                    # node's own new files against the TASK branch's CURRENT real state (never
                    # this node's own stale dispatch-time snapshot), applies clean line-hunks for
                    # a genuinely diverged file, re-checks the fence before every individual
                    # write, commits the merged result back to the TASK branch, and deletes this
                    # per-node branch in a `finally` regardless of outcome.
                    # Real, confirmed bug found live (2026-08-08/09, task
                    # 07141af5-9a4e-41b6-93ea-8b7af04fea9c's flagship run, service_ticket_model
                    # node, recurring identically across 4 consecutive rounds/resumes):
                    # `contract.frozen_old_files_by_relpath` is stored WITH the module-name
                    # prefix (raw vcs.read_last_validated_commit() output, e.g.
                    # 'oma_x_12345678/models/models.py') -- confirmed by this exact same
                    # function's OWN generation-side branch just above (`old_files_by_relpath`),
                    # which correctly strips this same prefix before use. But
                    # apply_node_result_to_module() below looks up `frozen_old_files_by_relpath.
                    # get(relpath, "")` using BARE relpaths (matching `new_files_by_relpath`'s own
                    # keying, e.g. 'models/models.py') -- the prefixed dict passed here NEVER
                    # matches, so every lookup silently returns "" instead of the real prior
                    # content. That empty "old_text" then forces `_apply_line_hunks()` to diff
                    # from nothing against the round's real new content, find no genuine shared
                    # anchor against a NON-empty current state, and report every already-existing
                    # file as a hard conflict -- deterministically, every single time ANY earlier
                    # constraint already wrote real content to a shared file (manifest, security
                    # CSV, etc.), which is exactly what a multi-constraint decomposed task's
                    # later nodes always inherit. Confirmed live: this recurred identically
                    # across 4 straight rounds/resumes, even after frozen_old_files_by_relpath's
                    # own separate staleness bug (resume not re-reading it fresh) was already
                    # fixed -- proving this prefix mismatch, not staleness, was the real,
                    # deterministic cause. Stripping the prefix here, the exact same way the
                    # generation-side branch already does, is the real fix.
                    module_prefix = f"{module_name}/"
                    frozen_old_files_bare = {
                        path.removeprefix(module_prefix): content
                        for path, content in (contract.frozen_old_files_by_relpath or {}).items()
                        if path.startswith(module_prefix)
                    }
                    apply_outcome = apply_node_result_to_module(
                        task_id=task_id_str, module_name=module_name, node_label=node_label,
                        frozen_old_files_by_relpath=frozen_old_files_bare,
                        node_new_files_by_relpath=new_files_by_relpath,
                        lock_key=lock_key, fence_token=lock.fence_token,
                        round_number=round_number_for_commit, summary=(generated.notes or "module update")[:200],
                    )
                    if not apply_outcome.success:
                        return SpecialistOutput(
                            task_id=contract.task_id,
                            specialist_type=contract.specialist_type,
                            summary=(
                                f"This round's own changes could not be merged against the task's "
                                f"CURRENT real state -- {apply_outcome.conflicted_relpaths!r} genuinely "
                                f"diverged since this node's own dispatch-time snapshot. Retrying will "
                                f"take a FRESH snapshot."
                            ),
                            detail={
                                "module_name": module_name,
                                "apply_conflict": True,
                                "conflicted_relpaths": apply_outcome.conflicted_relpaths,
                                "self_report_uncertain": generated.notes,
                                "commit_sha": commit_sha,
                            },
                            claims_complete=False,
                        )
                else:
                    _fenced_write_module_file("__manifest__.py", generated.manifest_py)
                    _fenced_write_module_file("models/models.py", generated.models_py)
                    _write_module_root_init_with_declared_hooks(generated, _fenced_write_module_file)
                    if generated.views_xml:
                        _fenced_write_module_file("views/views.xml", generated.views_xml)
                    else:
                        _fenced_delete_module_file("views/views.xml")
                    if generated.security_xml:
                        _fenced_write_module_file("security/security.xml", generated.security_xml)
                    else:
                        _fenced_delete_module_file("security/security.xml")
                    if generated.extra_data_files:
                        for extra_path, extra_content in generated.extra_data_files.items():
                            _fenced_write_module_file(extra_path, extra_content)
                    if generated.tests_py:
                        for test_path, test_content in generated.tests_py.items():
                            _fenced_write_module_file(test_path, test_content)
                    # Always overwrites odoo-bin scaffold's own placeholder --
                    # never leave that stale, model-mismatched row in place.
                    _fenced_write_module_file("security/ir.model.access.csv", generated.security_csv)
                publish_trace_event(task_id_str, {
                    "level": "specialist", "actor": "bug_fix", "message": generated.notes or "Wrote module files.", "status": "running",
                })
                # Phase 36 §0.9c (2026-08-13): fire-and-forget incremental Odoo Knowledge
                # Graph sync for exactly this module, right after its files are durably
                # written -- see tools_odoo/knowledge_graph/incremental_sync.py's own
                # docstring for the real write-point discrepancy vs. the plan doc's literal
                # text and the module_scope limitation this hook's own ETL call inherits.
                trigger_incremental_graph_sync(module_name, task_id=task_id_str)
                # Phase 35 §12.2/§13.3's real blast-radius/breakage check now runs
                # PRE-write, as a hard, blocking gate
                # (validate_no_blast_radius_collisions_or_breakage, wired into
                # _validate_generated_module()'s chain below) -- not here, post-write,
                # where a finding could only ever be logged, never actually prevented.

                diff = _compute_module_diff(old_files_by_relpath, new_files_by_relpath)
                # Phase 18 (§22.10): a small, deterministic, code-computed
                # check -- catches the exact confirmed regression shape
                # from §22.1 item 1 (a previously-satisfied constraint's
                # own content silently dropped) the SAME round it
                # happens, not several rounds later once Testing/QA
                # happens to notice the original requirement broke again.
                regressed_constraints = compute_regressed_constraints(
                    old_files_by_relpath, new_files_by_relpath, contract.constraint_status,
                    constraint_nodes=contract.constraint_nodes,
                )

                if sandbox_result.lint_result is not None:
                    # Phase 21 (2026-07-22): reuse the lint pass
                    # _sandbox_preflight() already ran CONCURRENTLY with
                    # its own install (on the sandbox's byte-identical
                    # copy of these same files) instead of paying
                    # pylint's own ~8-9s a second time here. None only
                    # when the sandbox step itself was skipped (the
                    # same-task-inherit fast path above), which never
                    # computes a lint result -- falls back to running
                    # it fresh in that case, same as always.
                    lint_result = sandbox_result.lint_result
                else:
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "bug_fix", "message": "Linting…", "status": "running",
                    })
                    lint_result = await asyncio.to_thread(lint_module, module_name)

                # Phase 35 §10.1 wiring (2026-08-12): a security-specific static analysis pass,
                # distinct from lint_module()'s functional/style pass above -- catches SQL
                # injection, dangerous builtins, and unscoped .sudo() calls, none of which
                # functional Code-Review or pylint-odoo were ever checking for. Informational on
                # this rollout, matching lint_result's own existing informational-only treatment
                # at this exact call site (lint findings have never blocked install here either)
                # -- but any HIGH-severity finding gets its own elevated-visibility trace event,
                # not silently folded into the ordinary lint noise. Wrapped in try/except and
                # explicitly logs its OWN failure too (a follow-up audit correctly caught that
                # this call site was the one Phase 35 safety mechanism in this revision that
                # silently degraded to no visibility at all on a tool-level failure -- Bandit
                # missing after a container rebuild, an SSH hiccup, a JSON parse error --
                # unlike run_pre_install_backup()/run_post_install_smoke_check(), which both
                # always publish a "FAILED (non-blocking)" event; this now matches that same
                # discipline rather than being a quieter exception to it).
                try:
                    security_lint_result = await asyncio.to_thread(security_lint_module, module_name)
                    if security_lint_result.ran_ok:
                        high_severity = [f for f in security_lint_result.findings if f.severity == "high"]
                        if high_severity:
                            publish_trace_event(task_id_str, {
                                "level": "specialist", "actor": "safety_net",
                                "message": (
                                    f"SECURITY FINDING: {len(high_severity)} high-severity issue(s) in "
                                    f"generated code: {[f.symbol for f in high_severity]}"
                                ),
                                "status": "failed",
                            })
                    else:
                        publish_trace_event(task_id_str, {
                            "level": "specialist", "actor": "safety_net",
                            "message": f"Security lint FAILED to run (non-blocking): {security_lint_result.raw_error}",
                            "status": "failed",
                        })
                except Exception as sec_lint_exc:  # noqa: BLE001 - a scanner failure must never block install
                    security_lint_result = LintResult(module_name=module_name, ran_ok=False, raw_error=str(sec_lint_exc))
                    publish_trace_event(task_id_str, {
                        "level": "specialist", "actor": "safety_net",
                        "message": f"Security lint raised (non-blocking): {sec_lint_exc}",
                        "status": "failed",
                    })

                if not check_fence(lock_key, lock.fence_token):
                    raise StaleForwardStepError(
                        f"fence check failed for {lock_key!r} before install -- another task "
                        f"has since taken over this model's lock; refusing to write."
                    )

                # Phase 35 §10.1 wiring (2026-08-12): back up the real Odoo filestore,
                # tagged to this exact task, immediately before the only call in this
                # codebase that installs a change into the real production db (self.db --
                # never the sandbox install at _sandbox_preflight()'s own, separate
                # call site). Best-effort, never blocks this install; see safety_net.py.
                await asyncio.to_thread(run_pre_install_backup, task_id_str)

                # Phase 35 §9.2 item 2 wiring (2026-08-12): reuse Odoo's own --test-enable
                # mechanism at the real production install, the same way sandbox preflight
                # already does above -- a real, previously-unused gap: install_module() has
                # supported test_enable since before this session, but this exact call site
                # (the only one that ever touches the real production database) never passed
                # it. See _should_test_enable_on_install()'s own docstring for why this checks
                # the module's real on-disk state, not just this round's own changed files.
                test_enable = _should_test_enable_on_install(module_name, new_files_by_relpath)

                publish_trace_event(task_id_str, {
                    "level": "specialist", "actor": "bug_fix", "message": f"Installing into {self.db}…", "status": "running",
                })
                install_result = await asyncio.to_thread(
                    install_module,
                    module_name, self.db, task_id=task_id_str, test_enable=test_enable,
                )
                completed_steps.append(
                    CompensatingAction(
                        forward_step=f"install module {module_name} into {self.db}",
                        undo_action=f"uninstall_module:{module_name}:{self.db}",
                    )
                )

                # P13 item 11, Unit 2 (docs/planning/PHASE30_OMA_SEAM_COVERAGE_AND_COMBINATORIAL_HARDENING_2026-07-29.md
                # §22.2 item 11): the join-suppression fix. A `state_verification_failed` install
                # whose EVERY structured finding (Unit 1, tools_odoo/module_dev/toolchain.py) is
                # fully explained by a not-yet-`satisfied` sibling constraint's own `creates`
                # artifacts is downgraded from a hard, round-budget-consuming failure to an
                # expected-incomplete result -- the real 0689823f-... stuck-task shape this item
                # exists to fix (a "no access rules" warning for a model the not-yet-reached
                # access_rights constraint would resolve). `contract.constraint_nodes` empty (the
                # common case -- fewer than 3 constraints, or a task that never decomposed) means
                # `not_yet_built_artifacts()` always returns an empty set, so
                # `is_expected_incomplete_finding()` can never fire and behavior is byte-for-byte
                # unchanged from before this fix -- no new failure mode for the majority of tasks.
                expected_incomplete_findings: list = []
                if (
                    not install_result.success
                    and install_result.error_kind == "state_verification_failed"
                    and install_result.findings
                    and contract.constraint_nodes
                ):
                    not_yet_built = not_yet_built_artifacts(contract.constraint_nodes, contract.constraint_status)
                    if all(
                        is_expected_incomplete_finding(f.artifact_names, not_yet_built)
                        for f in install_result.findings
                    ):
                        expected_incomplete_findings = install_result.findings

                # Phase 35 §9.2 item 1 wiring (2026-08-12): run the core-Odoo smoke suite
                # right after a real, successful production install -- monitor-only on
                # this rollout (does not change claims_complete below; see safety_net.py's
                # own docstring for why), but the result is logged with elevated
                # visibility and attached to this task's own detail payload so a human
                # reviewing it later can see whether anything else broke.
                smoke_check_result = (
                    await asyncio.to_thread(run_post_install_smoke_check, task_id_str, module_name, self.db)
                    if install_result.success else None
                )

                claims_complete = install_result.success or bool(expected_incomplete_findings)
                if install_result.success:
                    install_summary = "install succeeded"
                elif expected_incomplete_findings:
                    install_summary = (
                        f"install reported {install_result.error_kind!r}, but every finding is fully "
                        f"explained by a not-yet-built sibling constraint (expected-incomplete, not "
                        f"a real failure): {install_result.message}"
                    )
                else:
                    install_summary = f"install FAILED: {install_result.message}"
                summary = f"Scaffolded, wrote, and linted module {module_name!r}; {install_summary}"
                return SpecialistOutput(
                    task_id=contract.task_id,
                    specialist_type=contract.specialist_type,
                    summary=summary,
                    detail={
                        "module_name": module_name,
                        "db": self.db,
                        "lint_findings": [f.__dict__ for f in lint_result.findings],
                        "security_lint_findings": (
                            [f.__dict__ for f in security_lint_result.findings]
                            if security_lint_result.ran_ok else None
                        ),
                        "install_error_kind": install_result.error_kind,
                        "install_log_tail": install_result.log_tail,
                        "install_expected_incomplete_findings": [
                            f.__dict__ for f in expected_incomplete_findings
                        ],
                        "self_report_uncertain": generated.notes,
                        "compensating_actions_completed": [s.model_dump() for s in completed_steps],
                        "diff": diff,
                        "commit_sha": commit_sha,
                        "regressed_constraints": regressed_constraints,
                        "candidate_count": candidate_count_used,
                        "post_install_smoke_check": smoke_check_result,
                    },
                    claims_complete=claims_complete,
                    artifacts=[module_name],
                )
            except Exception as exc:
                if completed_steps:
                    raise PartialTaskFailure(exc, completed_steps) from exc
                raise
        finally:
            release_module_lock(lock_key, task_id_str)

    async def _validate_generated_module(
        self,
        generated: GeneratedModuleFiles,
        module_name: str,
        depends_on_module: str | None,
        old_models_py: str = "",
        old_views_xml: str = "",
        old_security_xml: str = "",
        old_manifest_py: str = "",
        old_files_by_relpath: dict[str, str] | None = None,
        constraint_status: dict | None = None,
        goal: str = "",
        original_goal: str | None = None,
        goal_facts: dict | None = None,
        task_id: str | None = None,
        remaining_constraint_labels: list[str] | None = None,
    ) -> None:
        """Every pre-write validator, run against one candidate's
        content -- factored out so Phase 18's best-of-N scoring (§22.7)
        can run it per candidate without duplicating the chain. Raises
        ValueError on the first failing check, exactly like every
        caller already expects (the single-candidate path below, and
        _generate_best_of_n()'s own per-candidate try/except).

        `old_models_py`/`constraint_status` are optional (default to a
        no-op for _validate_single_constraint_field_scope) purely so
        every EXISTING call site of this method didn't need updating
        the same day this was added -- callers on a real decomposed
        task should always pass both. `goal` (2026-07-20, UPDATE 20) is
        the same, optional-for-the-same-reason -- a caller on a
        decomposed round should always pass contract.goal so the
        premature-security-content autofix and its matching validator
        relaxation can see the round's own scope markers.
        """
        # Real, confirmed gap found live (2026-07-30): this whole
        # validator/autofix chain (60+ functions, several with real
        # awaited XML-RPC/DB lookups) published ZERO trace events --
        # confirmed live, a real 54s span with nothing visible in
        # between "Built views_xml deterministically" and "Sandbox
        # pre-flight" starting, the exact same silent-gap shape Phase
        # 21 (§21.10.1) already found and fixed once for a different
        # function. This start/end pair closes the visibility gap so a
        # slow chain is diagnosable from the real trace going forward,
        # without pinpointing (or changing the behavior of) any single
        # validator inside it yet -- a deliberately minimal, safe first
        # step, not a full profiling pass.
        _validate_chain_t0 = time.monotonic()
        if task_id:
            publish_trace_event(task_id, {
                "level": "specialist", "actor": "bug_fix",
                "message": "Running the pre-write validator/autofix chain…", "status": "running",
            })
        _autofix_lowercase_field_type_casing(generated)
        _autofix_dedupe_consecutive_identical_lines(generated)
        _autofix_dedupe_duplicate_special_model_attribute_assignments(generated)
        _validate_no_duplicate_odoo_special_attrs(generated)
        _autofix_dedupe_duplicate_method_definitions(generated)
        _validate_no_duplicate_method_definitions(generated)
        # 2026-08-04: real, confirmed gap found live in the same-night full 30-task sweep
        # (task004 round 2, and independently task016/019/022/027/028) -- both of these were
        # ALREADY narrow validators, but only ever wired into the internal loop's own
        # best-effort self-correction (run_build_internal_loop()), never into this hard external
        # gate. When the internal loop's own bounded patch budget couldn't self-correct in time
        # (an Escalate outcome), the still-broken candidate was written to disk and installed
        # anyway -- guaranteed to crash at Odoo's own registry-build time, wasting a full round
        # (task004's own round 2) on a 100% deterministic, mechanically-known-bad defect this
        # gate could have refused outright, the same way every other check in this chain does.
        # Reused verbatim (never reimplemented) -- same functions, same real live evidence.
        _validate_model_declares_name_or_inherit(generated)
        _validate_name_attribute_matches_odoo_naming_convention(generated)
        _validate_model_class_is_not_a_pure_identity_stub(generated, goal)
        _autofix_strip_stray_xml_attribute_fragment_lines(generated)
        _autofix_strip_invalid_field_use_attribute(generated)
        _validate_xml_is_well_formed(generated)
        _validate_no_empty_ref_attribute(generated)
        _validate_view_arch_has_single_root_element(generated)
        _validate_env_model_lookup_uses_dotted_model_name(generated)
        _validate_no_pseudo_field_groups_in_attrs_domain(generated)
        _validate_api_model_method_does_not_access_self_field_as_a_record(generated)
        _autofix_dedupe_duplicate_xml_record_ids(generated)
        _validate_no_duplicate_xml_record_ids(generated)
        _validate_no_view_record_self_inherits(generated)
        _autofix_restore_dropped_model_classes_in_shared_models_py(generated, old_files_by_relpath)
        _autofix_restore_dropped_inherit_extension_members_when_already_satisfied(generated, old_files_by_relpath, constraint_status)
        _autofix_hallucinated_model_base_class(generated)
        _autofix_new_model_inherit_string_to_list(generated)
        _autofix_models_py_missing_odoo_submodule_import(generated)
        _autofix_models_py_wrong_exception_module(generated)
        _autofix_missing_model_create_multi_decorator(generated)
        _autofix_missing_validation_error_import(generated)
        _autofix_strip_unrequested_views_xml_for_pure_behavior_task(generated, goal)
        _autofix_goal_named_search_filters_missing(generated, goal, constraint_status or {})
        _autofix_goal_named_stat_button_missing(generated, goal, constraint_status or {})
        _autofix_goal_literal_button_snippet_replaces_bare_field(generated, goal)
        _autofix_manifest_missing_views_reference(generated)
        _autofix_manifest_view_reference(generated)
        _autofix_manifest_stray_view_reference(generated)
        _validate_manifest_view_references(generated)
        _autofix_manifest_missing_security_xml_reference(generated)
        _autofix_manifest_security_xml_reference(generated)
        _autofix_manifest_stray_security_xml_reference(generated)
        _autofix_restore_dropped_manifest_data_reference(generated, old_manifest_py)
        _autofix_strip_misplaced_python_file_from_extra_data(generated)
        _autofix_manifest_stray_extra_data_file_reference(generated)
        _autofix_restore_dropped_records_in_shared_data_xml_file(generated, old_files_by_relpath)
        _autofix_ensure_extra_data_files_are_referenced_in_manifest(generated, old_files_by_relpath)
        _autofix_manifest_stray_unbacked_data_reference(generated, old_files_by_relpath)
        _validate_manifest_security_xml_references(generated)
        _autofix_bare_menu_restriction_id(generated)
        _autofix_ir_cron_deprecated_function_field(generated)
        _autofix_escape_angle_brackets_in_cron_code_field(generated)
        _validate_ir_cron_no_self_referential_env_lookup(generated)
        _autofix_manifest_missing_dependency_for_cross_module_record_id(generated, module_name)
        await _timed_validator_step(task_id, "_autofix_rewrite_own_task_model_name_to_inherit",
            _autofix_rewrite_own_task_model_name_to_inherit(generated, goal, self.db, module_name, task_id=task_id))
        # Real, confirmed bug found live (2026-08-03, task027's own real re-test, same day as the
        # dedup autofix above): _autofix_rewrite_own_task_model_name_to_inherit() rewrites a
        # `_name = 'X'` line to `_inherit = 'X'` -- if the file ALREADY had its own real
        # `_inherit = [...]` line (e.g. from an earlier scoped-edit round), this rewrite creates a
        # FRESH duplicate `_inherit` assignment that the dedup pass earlier in this same chain
        # never had a chance to see (it already ran before this rewrite). Confirmed live via debug
        # instrumentation: models_py reaching this exact point still had two undeduped `_inherit`
        # lines. Re-running the same dedup here catches exactly this new duplicate; it's a pure
        # no-op whenever this rewrite didn't introduce one.
        _autofix_dedupe_duplicate_special_model_attribute_assignments(generated)
        _autofix_dedupe_consecutive_identical_lines(generated)
        _validate_new_model_name_is_valid_odoo_identifier(generated)
        await _timed_validator_step(task_id, "_validate_new_model_name_not_already_real",
            _validate_new_model_name_not_already_real(generated, self.db, module_name, task_id=task_id))
        await _timed_validator_step(task_id, "_validate_no_new_field_collides_with_real_target_field",
            _validate_no_new_field_collides_with_real_target_field(generated, old_models_py, self.db, task_id=task_id))
        _autofix_manifest_security_csv_reference(generated)
        _autofix_manifest_missing_security_csv_data_reference(generated)
        _autofix_wrong_module_prefixed_local_group_id(generated, module_name)
        _autofix_restore_dropped_rows_in_shared_security_csv(generated, old_files_by_relpath)
        _autofix_security_csv_drops_inherit_only_rows(generated, old_files_by_relpath, goal)
        _autofix_zero_unlink_for_rule_scoped_group_access_row(generated, old_files_by_relpath)
        _autofix_strip_goal_explicitly_required_removed_access_row(generated, goal)
        _autofix_synthesize_goal_named_restricted_access_rows(generated, goal, depends_on_module)
        _autofix_strip_premature_security_content_on_decomposed_round(generated, goal, constraint_status)
        _autofix_restore_dropped_security_content_when_already_satisfied(generated, constraint_status, old_security_xml)
        _autofix_strip_premature_views_content_on_decomposed_round(generated, goal, constraint_status)
        _autofix_restore_dropped_views_content_when_already_satisfied(generated, constraint_status, old_views_xml)
        _autofix_restore_dropped_view_records_in_shared_views_xml(generated, old_views_xml, constraint_status)
        _autofix_strip_premature_computed_field_on_decomposed_round(generated, goal, constraint_status)
        await _timed_validator_step(task_id, "_autofix_manifest_missing_dependency_for_csv_model_refs",
            _autofix_manifest_missing_dependency_for_csv_model_refs(
                generated, self.db, module_name, task_id=task_id, depends_on_module=depends_on_module))
        # Real, confirmed bug found live (2026-07-16, Phase 20 Area 2), via
        # temporary object-identity instrumentation after static analysis
        # alone couldn't explain it: this stripper used to run FIRST (right
        # after the manifest-literal check), correctly removing a
        # hallucinated 'oma_create_a_small_new_XXXXXXXX' dependency -- but
        # the two ADDER autofixes above it (cross-module-record-id and
        # csv-model-ref) run LATER and blindly trust whatever module
        # prefix they find in a security_xml `<record id="module.x">` or
        # a security_csv `model_id:id` value, with no way to know that
        # prefix was ITSELF a hallucination -- so a hallucinated
        # cross-reference INSIDE the XML/CSV content (not just the
        # manifest's own depends list) caused the adders to blindly add
        # the exact same bad dependency straight back, undoing the
        # stripper silently. Confirmed via real object-id tracing: the
        # SAME candidate object's manifest_py gained the hallucinated
        # dependency back between the stripper running and the final
        # winner being used to write files. Moved to run LAST, after both
        # adders, so it has final say regardless of which earlier step
        # (LLM generation or an adder) introduced the bad reference.
        _autofix_manifest_hallucinated_custom_module_dependency(generated, module_name, depends_on_module)
        # Promoted 2026-07-30 from the Phase 29 rule-learning backlog
        # (source rows 5266/5268): catches a fully empty security_csv,
        # distinct from the deliberate header-only case produced by
        # _autofix_strip_premature_security_content_on_decomposed_round
        # above (which _validate_security_csv_covers_new_models below
        # already tolerates on an unscoped round) -- placed here, after
        # every autofix that can write/strip security_csv content, so it
        # only ever sees the round's final, settled value.
        _validate_security_csv_not_empty(generated)
        _validate_security_csv_row_column_count_matches_header(generated)
        _validate_security_csv_covers_new_models(generated, goal)
        _autofix_synthesize_missing_res_groups_record_for_csv_referenced_group(generated, module_name)
        _validate_security_csv_group_id_refers_to_a_defined_group(generated, module_name)
        _autofix_strip_premature_invented_field_on_views_focused_round(generated, goal, original_goal)
        _autofix_strip_empty_inherit_only_extension_classes(generated)
        _validate_inherit_only_class_is_not_empty(generated, goal)
        _validate_no_invented_field_on_views_focused_round(generated, goal, original_goal)
        _validate_compute_field_depends_does_not_include_itself(generated)
        _validate_compute_field_depends_does_not_reference_other_models_own_fk_field(generated)
        _validate_view_fields_exist_on_model(generated)
        _validate_xml_record_field_value_within_char_size_limit(generated)
        await _timed_validator_step(task_id, "_validate_view_fields_exist_on_inherited_model",
            _validate_view_fields_exist_on_inherited_model(
                generated, self.db, task_id=task_id, old_models_py=old_models_py,
            ))
        await _timed_validator_step(task_id, "_validate_references_resolve_against_real_target",
            _validate_references_resolve_against_real_target(generated, self.db, module_name, task_id=task_id))
        _validate_single_constraint_field_scope(generated, old_models_py, constraint_status or {})
        _validate_no_premature_out_of_scope_method(generated, goal, old_models_py, constraint_status or {})
        _autofix_goal_named_sum_compute_field_missing(generated, goal, constraint_status or {})
        _autofix_goal_named_computed_field_missing_declaration(generated, goal, constraint_status or {}, goal_facts)
        _autofix_goal_named_sequence_field_missing(generated, goal, constraint_status or {}, goal_facts)
        _autofix_goal_named_field_declaration_missing(generated, goal, constraint_status or {}, goal_facts)
        # P11 fifth pass item 176 (docs/planning/PHASE30_SECOND_PASS_FINAL_CONSOLIDATED_2026-07-30.md
        # §1.1): moved from its old position (step ~14, right after _autofix_missing_validation_
        # error_import) to run HERE, after both step 55/57 field-declaring autofixes above.
        # Real, confirmed bug this closes: this function snapshots real_fields from models_py and
